test_that("test_array_expressions: test_zero_array matches SymPy", {
  expect_equal(.bat_fmt(local({ZeroArray()})), "0")
  expect_equal(.bat_fmt(local({v_za <- ZeroArray(Integer(3), Integer(2), Integer(4)); get_shape(v_za)})), "[3, 2, 4]")
  expect_equal(.bat_fmt(local({list(3, 2, 4)})), "[3, 2, 4]")
  expect_equal(.bat_fmt(local({v_za <- ZeroArray(Symbol("m"), Symbol("n"), Symbol("k"), Integer(2)); get_shape(v_za)})), "[m, n, k, 2]")
  expect_equal(.bat_fmt(local({v_m <- Symbol("m"); v_n <- Symbol("n"); v_k <- Symbol("k"); list(v_m, v_n, v_k, 2)})), "[m, n, k, 2]")
  expect_error(local({v_za <- ZeroArray(Symbol("m"), Symbol("n"), Symbol("k"), Integer(2)); as_explicit(v_za)}), "Cannot return explicit form for symbolic shape.", fixed = TRUE, class = "ValueError")
})

test_that("test_array_expressions: test_one_array matches SymPy", {
  expect_equal(.bat_fmt(local({OneArray()})), "1")
  expect_equal(.bat_fmt(local({v_oa <- OneArray(Integer(3), Integer(2), Integer(4)); get_shape(v_oa)})), "[3, 2, 4]")
  expect_equal(.bat_fmt(local({v_oa <- OneArray(Symbol("m"), Symbol("n"), Symbol("k"), Integer(2)); get_shape(v_oa)})), "[m, n, k, 2]")
  expect_error(local({v_oa <- OneArray(Symbol("m"), Symbol("n"), Symbol("k"), Integer(2)); as_explicit(v_oa)}), "Cannot return explicit form for symbolic shape.", fixed = TRUE, class = "ValueError")
})

test_that("test_array_expressions: test_arrayexpr_contraction_construction matches SymPy", {
  expect_equal(.bat_fmt(local({v_cg <- ArraySymbol(Symbol("A"), Tuple(Symbol("k"), Symbol("k"))); v_cg})), "A")
  expect_equal(.bat_fmt(local({v_A <- ArraySymbol(Symbol("A"), Tuple(Symbol("k"), Symbol("k"))); v_A})), "A")
  expect_equal(.bat_fmt(local({v_cg <- ArrayContraction(ArrayTensorProduct(ArraySymbol(Symbol("A"), Tuple(Symbol("k"), Symbol("k"))), ArraySymbol(Symbol("B"), Tuple(Symbol("k"), Symbol("k")))), Tuple(Integer(0), Integer(1))); v_cg})), "ArrayContraction(ArrayTensorProduct(A, B), (0, 1))")
  expect_equal(.bat_fmt(local({v_A <- ArraySymbol(Symbol("A"), Tuple(Symbol("k"), Symbol("k"))); v_B <- ArraySymbol(Symbol("B"), Tuple(Symbol("k"), Symbol("k"))); symcompR:::.array_contraction(symcompR:::.array_tensor_product(v_A, v_B), list(0, 1))})), "ArrayContraction(ArrayTensorProduct(A, B), (0, 1))")
  expect_equal(.bat_fmt(local({v_indtup <- list(list(list(0, 0), list(0, 1))); v_indtup})), "[[[0, 0], [0, 1]]]")
  expect_equal(.bat_fmt(local({list(list(list(0, 0), list(0, 1)))})), "[[[0, 0], [0, 1]]]")
  expect_equal(.bat_fmt(local({list(list(0, 1))})), "[[0, 1]]")
  expect_equal(.bat_fmt(local({v_indtup <- list(list(list(0, 1), list(1, 0))); v_indtup})), "[[[0, 1], [1, 0]]]")
  expect_equal(.bat_fmt(local({list(list(list(0, 1), list(1, 0)))})), "[[[0, 1], [1, 0]]]")
  expect_equal(.bat_fmt(local({list(list(1, 2))})), "[[1, 2]]")
  expect_equal(.bat_fmt(local({v_indtup <- list(list(list(0, 0), list(1, 1)), list(list(0, 1), list(2, 0))); v_indtup})), "[[[0, 0], [1, 1]], [[0, 1], [2, 0]]]")
  expect_equal(.bat_fmt(local({list(list(list(0, 0), list(1, 1)), list(list(0, 1), list(2, 0)))})), "[[[0, 0], [1, 1]], [[0, 1], [2, 0]]]")
  expect_equal(.bat_fmt(local({list(list(0, 3), list(1, 4))})), "[[0, 3], [1, 4]]")
  expect_equal(.bat_fmt(local({v_a <- ArraySymbol(Symbol("a"), Tuple(Symbol("k"), Integer(1))); symcompR:::.array_contraction(v_a, list(1))})), "Reshape(a, (k,))")
  expect_equal(.bat_fmt(local({v_a <- ArraySymbol(Symbol("a"), Tuple(Symbol("k"), Integer(1))); v_k <- Symbol("k"); Reshape(v_a, list(v_k))})), "Reshape(a, (k,))")
  expect_equal(.bat_fmt(local({v_a <- ArraySymbol(Symbol("a"), Tuple(Symbol("k"), Integer(1))); get_shape(symcompR:::.array_contraction(v_a, list(1)))})), "[k]")
  expect_equal(.bat_fmt(local({v_a <- ArraySymbol(Symbol("a"), Tuple(Symbol("k"), Integer(1))); get_shape(ArrayContraction(v_a, list(1)))})), "[k]")
  expect_equal(.bat_fmt(local({v_k <- Symbol("k"); list(v_k)})), "[k]")
  expect_equal(.bat_fmt(local({v_expr <- ArrayContraction(ArrayTensorProduct(ArraySymbol(Symbol("a"), Tuple(Symbol("k"), Integer(1))), ArraySymbol(Symbol("b"), Tuple(Symbol("k"), Integer(1)))), Tuple(Integer(0), Integer(2)), Tuple(Integer(1)), Tuple(Integer(3))); get_shape(v_expr)})), "[]")
  expect_equal(.bat_fmt(local({v_a <- ArraySymbol(Symbol("a"), Tuple(Symbol("k"), Integer(1))); v_b <- ArraySymbol(Symbol("b"), Tuple(Symbol("k"), Integer(1))); get_shape(ArrayContraction(symcompR:::.array_tensor_product(v_a, v_b), list(0, 2), list(1), list(3)))})), "[]")
})

