  expect_equal(.bat_fmt(local({v_expr <- ArrayTensorProduct(ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))), ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))), ArraySymbol(Symbol("P"), Tuple(Symbol("k"), Symbol("k"))), ArraySymbol(Symbol("Q"), Tuple(Symbol("k"), Symbol("k")))); v_expr})), "ArrayTensorProduct(M, N, P, Q)")
  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); v_P <- ArraySymbol(Symbol("P"), Tuple(Symbol("k"), Symbol("k"))); v_Q <- ArraySymbol(Symbol("Q"), Tuple(Symbol("k"), Symbol("k"))); symcompR:::.array_tensor_product(v_M, v_N, v_P, v_Q)})), "ArrayTensorProduct(M, N, P, Q)")
  expect_equal(.bat_fmt(local({v_expr <- ArrayTensorProduct(ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))), ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))), ArraySymbol(Symbol("P"), Tuple(Symbol("k"), Symbol("k"))), ArraySymbol(Symbol("Q"), Tuple(Symbol("k"), Symbol("k")))); sym_args(v_expr)})), "[M, N, P, Q]")
  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); v_P <- ArraySymbol(Symbol("P"), Tuple(Symbol("k"), Symbol("k"))); v_Q <- ArraySymbol(Symbol("Q"), Tuple(Symbol("k"), Symbol("k"))); list(v_M, v_N, v_P, v_Q)})), "[M, N, P, Q]")
