  expect_equal(.bat_fmt(local({v_expr <- ArrayContraction(ArrayTensorProduct(ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))), ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))), ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k")))), Tuple(Integer(3), Integer(4))); v_expr})), "ArrayContraction(ArrayTensorProduct(M, M, N), (3, 4))")
  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); symcompR:::.array_contraction(symcompR:::.array_tensor_product(v_M, v_M, v_N), list(3, 4))})), "ArrayContraction(ArrayTensorProduct(M, M, N), (3, 4))")
