  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); symcompR:::.array_contraction(symcompR:::.array_tensor_product(v_M, v_N), list(0, 3), list(1, 2))})), "ArrayContraction(ArrayTensorProduct(M, N), (0, 3), (1, 2))")
