test_that("test_array_expressions: test_arrayexpr_tensor_product_scalar_coefficients matches SymPy", {
  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_y <- Symbol("y"); v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); doit(ArrayTensorProduct(v_x, v_M, v_y, v_N))})), "ArrayTensorProduct(x*y, M, N)")
  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_y <- Symbol("y"); v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); ArrayTensorProduct((v_x * v_y), v_M, v_N)})), "ArrayTensorProduct(x*y, M, N)")
  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_y <- Symbol("y"); v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); get_shape(doit(ArrayTensorProduct(v_x, v_M, v_y, v_N)))})), "[k, k, k, k]")
  expect_equal(.bat_fmt(local({v_k <- Symbol("k"); list(v_k, v_k, v_k, v_k)})), "[k, k, k, k]")
  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); doit(ArrayTensorProduct(2, v_M, 3, v_N))})), "ArrayTensorProduct(6, M, N)")
  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); ArrayTensorProduct(6, v_M, v_N)})), "ArrayTensorProduct(6, M, N)")
  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); doit(ArrayTensorProduct(0, v_M, v_N))})), "ZeroArray(k, k, k, k)")
  expect_equal(.bat_fmt(local({v_k <- Symbol("k"); ZeroArray(v_k, v_k, v_k, v_k)})), "ZeroArray(k, k, k, k)")
  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); doit(ArrayTensorProduct(v_x, v_M, 0, v_N))})), "ZeroArray(k, k, k, k)")
  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_y <- Symbol("y"); doit(ArrayTensorProduct(v_x, v_y))})), "x*y")
  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_y <- Symbol("y"); (v_x * v_y)})), "x*y")
  expect_equal(.bat_fmt(local({v_tp <- ArrayTensorProduct(Integer(2), ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))), ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k")))); sym_args(v_tp)})), "[2, M, N]")
  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); list(2, v_M, v_N)})), "[2, M, N]")
  expect_equal(.bat_fmt(local({v_tp <- ArrayTensorProduct(Integer(2), ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))), ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k")))); get_shape(v_tp)})), "[k, k, k, k]")
  expect_equal(.bat_fmt(local({v_tp <- ArrayTensorProduct(Integer(2), ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))), ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k")))); doit(v_tp)})), "ArrayTensorProduct(2, M, N)")
  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); ArrayTensorProduct(2, v_M, v_N)})), "ArrayTensorProduct(2, M, N)")
  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_y <- Symbol("y"); v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); doit(ArrayTensorProduct(((v_x * v_y) * v_M), v_N))})), "ArrayTensorProduct(x*y, M, N)")
  expect_equal(.bat_fmt(local({v_Ms <- MatrixSymbol("Ms", Symbol("k"), Symbol("k")); v_Ns <- MatrixSymbol("Ns", Symbol("k"), Symbol("k")); doit(ArrayTensorProduct((2 * v_Ms), v_Ns))})), "ArrayTensorProduct(2, Ms, Ns)")
  expect_equal(.bat_fmt(local({v_Ms <- MatrixSymbol("Ms", Symbol("k"), Symbol("k")); v_Ns <- MatrixSymbol("Ns", Symbol("k"), Symbol("k")); ArrayTensorProduct(2, v_Ms, v_Ns)})), "ArrayTensorProduct(2, Ms, Ns)")
  expect_equal(.bat_fmt(local({v_Ms <- MatrixSymbol("Ms", Symbol("k"), Symbol("k")); v_Ns <- MatrixSymbol("Ns", Symbol("k"), Symbol("k")); doit(ArrayTensorProduct((2 * v_Ms), (3 * v_Ns)))})), "ArrayTensorProduct(6, Ms, Ns)")
  expect_equal(.bat_fmt(local({v_Ms <- MatrixSymbol("Ms", Symbol("k"), Symbol("k")); v_Ns <- MatrixSymbol("Ns", Symbol("k"), Symbol("k")); ArrayTensorProduct(6, v_Ms, v_Ns)})), "ArrayTensorProduct(6, Ms, Ns)")
  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_Ms <- MatrixSymbol("Ms", Symbol("k"), Symbol("k")); v_Ns <- MatrixSymbol("Ns", Symbol("k"), Symbol("k")); v_y <- Symbol("y"); doit(ArrayTensorProduct(((v_x * v_Ms) * v_Ns), (v_y * v_Ns)))})), "ArrayTensorProduct(x*y, Ms*Ns, Ns)")
  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_y <- Symbol("y"); v_Ms <- MatrixSymbol("Ms", Symbol("k"), Symbol("k")); v_Ns <- MatrixSymbol("Ns", Symbol("k"), Symbol("k")); ArrayTensorProduct((v_x * v_y), (v_Ms * v_Ns), v_Ns)})), "ArrayTensorProduct(x*y, Ms*Ns, Ns)")
  expect_equal(.bat_fmt(local({v_tr <- ArrayContraction(MatrixSymbol("Ms", Symbol("k"), Symbol("k")), Tuple(Integer(0), Integer(1))); symcompR:::.array_tensor_product(3, v_tr)})), "ArrayContraction(ArrayTensorProduct(3, Ms), (0, 1))")
  expect_equal(.bat_fmt(local({v_Ms <- MatrixSymbol("Ms", Symbol("k"), Symbol("k")); ArrayContraction(ArrayTensorProduct(3, v_Ms), list(0, 1))})), "ArrayContraction(ArrayTensorProduct(3, Ms), (0, 1))")
  expect_equal(.bat_fmt(local({v_Ms <- MatrixSymbol("Ms", Symbol("k"), Symbol("k")); symcompR:::.split_scalar_coefficient((2 * v_Ms))})), "[2, Ms]")
  expect_equal(.bat_fmt(local({v_Ms <- MatrixSymbol("Ms", Symbol("k"), Symbol("k")); list(2, v_Ms)})), "[2, Ms]")
  expect_equal(.bat_fmt(local({v_Ms <- MatrixSymbol("Ms", Symbol("k"), Symbol("k")); symcompR:::.split_scalar_coefficient(v_Ms)})), "[1, Ms]")
  expect_equal(.bat_fmt(local({v_Ms <- MatrixSymbol("Ms", Symbol("k"), Symbol("k")); list(S_One, v_Ms)})), "[1, Ms]")
  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_y <- Symbol("y"); symcompR:::.split_scalar_coefficient((v_x * v_y))})), "[x*y, None]")
  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_y <- Symbol("y"); list((v_x * v_y), NULL)})), "[x*y, None]")
  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); symcompR:::.split_scalar_coefficient((2 * v_M))})), "[2, M]")
  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); list(2, v_M)})), "[2, M]")
})

