  expect_equal(.bat_fmt(local({v_za1 <- ZeroArray(Symbol("k"), Symbol("l"), Symbol("m"), Symbol("n")); symcompR:::.permute_dims(v_za1, list(2, 1, 3, 0))})), "ZeroArray(m, l, n, k)")
  expect_equal(.bat_fmt(local({v_m <- Symbol("m"); v_l <- Symbol("l"); v_n <- Symbol("n"); v_k <- Symbol("k"); ZeroArray(v_m, v_l, v_n, v_k)})), "ZeroArray(m, l, n, k)")
  expect_equal(.bat_fmt(local({v_zm1 <- ZeroMatrix(Symbol("m"), Symbol("n")); symcompR:::.permute_dims(v_zm1, list(1, 0))})), "ZeroArray(n, m)")
  expect_equal(.bat_fmt(local({v_n <- Symbol("n"); v_m <- Symbol("m"); ZeroArray(v_n, v_m)})), "ZeroArray(n, m)")
  expect_equal(.bat_fmt(local({v_za1 <- ZeroArray(Symbol("k"), Symbol("l"), Symbol("m"), Symbol("n")); symcompR:::.array_add(v_za1)})), "ZeroArray(k, l, m, n)")
