  expect_equal(.bat_fmt(local({v_tp1 <- ArrayTensorProduct(MatrixSymbol("A", Symbol("k"), Symbol("l")), MatrixSymbol("B", Symbol("m"), Symbol("n"))); v_za1 <- ZeroArray(Symbol("k"), Symbol("l"), Symbol("m"), Symbol("n")); symcompR:::.array_add(v_tp1, v_za1)})), "ArrayTensorProduct(A, B)")
