  expect_equal(.bat_fmt(local({v_tp1 <- ArrayTensorProduct(MatrixSymbol("A", Symbol("k"), Symbol("l")), MatrixSymbol("B", Symbol("m"), Symbol("n"))); v_za1 <- ZeroArray(Symbol("k"), Symbol("l"), Symbol("m"), Symbol("n")); v_tp2 <- ArrayTensorProduct(MatrixSymbol("C", Symbol("k"), Symbol("l")), MatrixSymbol("D", Symbol("m"), Symbol("n"))); symcompR:::.array_add(v_tp1, v_za1, v_tp2)})), "ArrayAdd(ArrayTensorProduct(A, B), ArrayTensorProduct(C, D))")
  expect_equal(.bat_fmt(local({v_tp1 <- ArrayTensorProduct(MatrixSymbol("A", Symbol("k"), Symbol("l")), MatrixSymbol("B", Symbol("m"), Symbol("n"))); v_tp2 <- ArrayTensorProduct(MatrixSymbol("C", Symbol("k"), Symbol("l")), MatrixSymbol("D", Symbol("m"), Symbol("n"))); symcompR:::.array_add(v_tp1, v_tp2)})), "ArrayAdd(ArrayTensorProduct(A, B), ArrayTensorProduct(C, D))")
