  expect_error(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_i <- Symbol("i"); symcompR:::.array_add(v_M, v_i)}), "scalar arguments are not allowed in ArrayAdd", fixed = TRUE, class = "TypeError")
  expect_equal(.bat_fmt(local({v_expr <- ArrayAdd(ArrayContraction(ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(1))), ArrayContraction(ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(1)))); doit(v_expr)})), "ArrayAdd(ArrayContraction(M, (0, 1)), ArrayContraction(N, (0, 1)))")
