  expect_equal(.bat_fmt(local({v_expr <- PermuteDims(PermuteDims(ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))), Permutation(c(1, 0))), Permutation(c(1, 0))); sstr(v_expr)})), "PermuteDims(PermuteDims(M, (0 1)), (0 1))")
  expect_equal(.bat_fmt(local({v_expr <- PermuteDims(PermuteDims(ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))), Permutation(c(1, 0))), Permutation(c(1, 0))); doit(v_expr)})), "M")
  expect_equal(.bat_fmt(local({v_expr <- PermuteDims(PermuteDims(PermuteDims(ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))), Permutation(c(1, 0))), Permutation(c(1, 0))), Permutation(c(1, 0))); doit(v_expr)})), "PermuteDims(M, (0 1))")
  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); PermuteDims(v_M, list(1, 0))})), "PermuteDims(M, (0 1))")
  expect_equal(.bat_fmt(local({v_expr <- Reshape(ArraySymbol(Symbol("A"), Tuple(Symbol("k"), Symbol("k"))), Tuple((Symbol("k"))^(Integer(2)))); get_shape(v_expr)})), "[k^2]")
