test_that("test_array_expressions: test_array_element_expressions matches SymPy", {
  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); (pyitem(v_M, 0, 0) * pyitem(v_N, 0, 0))})), "M[0, 0]*N[0, 0]")
  expect_equal(.bat_fmt(local({v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); (pyitem(v_N, 0, 0) * pyitem(v_M, 0, 0))})), "M[0, 0]*N[0, 0]")
  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); diff(pyitem(v_M, 0, 0), pyitem(v_M, 0, 0))})), "1")
  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); diff(pyitem(v_M, 0, 0), pyitem(v_M, 1, 0))})), "0")
  expect_equal(.bat_fmt(local({v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); diff(pyitem(v_M, 0, 0), pyitem(v_N, 0, 0))})), "0")
  expect_equal(.bat_fmt(local({v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); v_i <- Symbol("i"); v_j <- Symbol("j"); diff(pyitem(v_M, 0, 1), pyitem(v_M, v_i, v_j))})), "KroneckerDelta(0, i)*KroneckerDelta(1, j)")
  expect_equal(.bat_fmt(local({v_i <- Symbol("i"); v_j <- Symbol("j"); (KroneckerDelta(v_i, 0) * KroneckerDelta(v_j, 1))})), "KroneckerDelta(0, i)*KroneckerDelta(1, j)")
  expect_equal(.bat_fmt(local({v_N <- ArraySymbol(Symbol("N"), Tuple(Symbol("k"), Symbol("k"))); v_i <- Symbol("i"); v_j <- Symbol("j"); v_M <- ArraySymbol(Symbol("M"), Tuple(Symbol("k"), Symbol("k"))); diff(pyitem(v_M, 0, 1), pyitem(v_N, v_i, v_j))})), "0")
  expect_equal(.bat_fmt(local({v_K4 <- ArraySymbol(Symbol("K4"), Tuple(Symbol("k"), Symbol("k"), Symbol("k"), Symbol("k"))); v_i <- Symbol("i"); v_j <- Symbol("j"); v_k <- Symbol("k"); v_l <- Symbol("l"); diff(pyitem(v_K4, v_i, v_j, v_k, v_l), pyitem(v_K4, 1, 2, 3, 4))})), "KroneckerDelta(1, i)*KroneckerDelta(2, j)*KroneckerDelta(3, k)*KroneckerDelta(4, l)")
  expect_equal(.bat_fmt(local({v_i <- Symbol("i"); v_j <- Symbol("j"); v_k <- Symbol("k"); v_l <- Symbol("l"); (((KroneckerDelta(v_i, 1) * KroneckerDelta(v_j, 2)) * KroneckerDelta(v_k, 3)) * KroneckerDelta(v_l, 4))})), "KroneckerDelta(1, i)*KroneckerDelta(2, j)*KroneckerDelta(3, k)*KroneckerDelta(4, l)")
})

