test_that("test_array_expressions: test_array_sum matches SymPy", {
  expect_equal(.bat_fmt(local({v_expr <- ArraySum(MatrixSymbol("X", Symbol("k"), Symbol("k")), list(Symbol("i"), Integer(1), Symbol("j"))); v_expr})), "Sum(X, (i, 1, j))")
  expect_equal(.bat_fmt(local({v_expr <- ArraySum(MatrixSymbol("X", Symbol("k"), Symbol("k")), list(Symbol("i"), Integer(1), Symbol("j"))); doit(v_expr)})), "j*X")
  expect_equal(.bat_fmt(local({v_j <- Symbol("j"); v_X <- MatrixSymbol("X", Symbol("k"), Symbol("k")); (v_j * v_X)})), "j*X")
  expect_equal(.bat_fmt(local({v_expr <- ArraySum(MatrixSymbol("X", Symbol("k"), Symbol("k")), list(Symbol("i"), Integer(1), Integer(5))); doit(v_expr)})), "5*X")
  expect_equal(.bat_fmt(local({v_X <- MatrixSymbol("X", Symbol("k"), Symbol("k")); (5 * v_X)})), "5*X")
  expect_equal(.bat_fmt(local({v_expr <- ArrayTensorProduct(ArraySum(MatrixSymbol("X", Symbol("k"), Symbol("k")), list(Symbol("i"), Integer(1), Integer(5))), MatrixSymbol("Y", Symbol("k"), Symbol("k"))); doit(v_expr)})), "ArrayTensorProduct(5, X, Y)")
  expect_equal(.bat_fmt(local({v_X <- MatrixSymbol("X", Symbol("k"), Symbol("k")); v_Y <- MatrixSymbol("Y", Symbol("k"), Symbol("k")); ArrayTensorProduct(5, v_X, v_Y)})), "ArrayTensorProduct(5, X, Y)")
  expect_equal(.bat_fmt(local({v_expr <- ArrayTensorProduct(ArraySymbol(Symbol("A"), Tuple(Symbol("k"), Symbol("k"))), ArraySum(MatrixSymbol("X", Symbol("k"), Symbol("k")), list(Symbol("i"), Integer(1), Symbol("j"))), ArraySymbol(Symbol("B"), Tuple(Symbol("k"), Symbol("k"))), ArraySum(MatrixSymbol("Y", Symbol("k"), Symbol("k")), list(Symbol("i"), Integer(1), Symbol("m"))), ArraySymbol(Symbol("C"), Tuple(Symbol("k"), Symbol("k")))); doit(v_expr)})), "ArrayTensorProduct(j*m, A, X, B, Y, C)")
  expect_equal(.bat_fmt(local({v_j <- Symbol("j"); v_m <- Symbol("m"); v_A <- ArraySymbol(Symbol("A"), Tuple(Symbol("k"), Symbol("k"))); v_X <- MatrixSymbol("X", Symbol("k"), Symbol("k")); v_B <- ArraySymbol(Symbol("B"), Tuple(Symbol("k"), Symbol("k"))); v_Y <- MatrixSymbol("Y", Symbol("k"), Symbol("k")); v_C <- ArraySymbol(Symbol("C"), Tuple(Symbol("k"), Symbol("k"))); ArrayTensorProduct((v_j * v_m), v_A, v_X, v_B, v_Y, v_C)})), "ArrayTensorProduct(j*m, A, X, B, Y, C)")
  expect_equal(.bat_fmt(local({v_expr <- ArrayTensorProduct(ArraySymbol(Symbol("A"), Tuple(Symbol("k"), Symbol("k"))), ArraySum(MatMul(sin(Symbol("i")), MatrixSymbol("X", Symbol("k"), Symbol("k"))), list(Symbol("i"), Integer(1), Symbol("j"))), ArraySymbol(Symbol("B"), Tuple(Symbol("k"), Symbol("k"))), ArraySum(MatMul(sin(Symbol("i")), MatrixSymbol("Y", Symbol("k"), Symbol("k"))), list(Symbol("i"), Integer(1), Symbol("m"))), ArraySymbol(Symbol("C"), Tuple(Symbol("k"), Symbol("k")))); doit(v_expr)})), "Sum(ArrayTensorProduct(sin(_i)*sin(_i), A, X, B, Y, C), (_i, 1, j), (_i, 1, m))")
  expect_equal(.bat_fmt(local({v_i <- Symbol("i"); v_n <- Symbol("n"); v_A <- ArraySymbol(Symbol("A"), Tuple(Symbol("k"), Symbol("k"))); v_X <- MatrixSymbol("X", Symbol("k"), Symbol("k")); v_B <- ArraySymbol(Symbol("B"), Tuple(Symbol("k"), Symbol("k"))); v_Y <- MatrixSymbol("Y", Symbol("k"), Symbol("k")); v_C <- ArraySymbol(Symbol("C"), Tuple(Symbol("k"), Symbol("k"))); v_j <- Symbol("j"); v_m <- Symbol("m"); ArraySum(ArrayTensorProduct((sin(v_i) * sin(v_n)), v_A, v_X, v_B, v_Y, v_C), list(v_i, 1, v_j), list(v_n, 1, v_m))})), "Sum(ArrayTensorProduct(sin(i)*sin(n), A, X, B, Y, C), (i, 1, j), (n, 1, m))")
  expect_equal(.bat_fmt(local({v_expr <- ArrayTensorProduct(ArraySum(MatPow(MatrixSymbol("X", Symbol("k"), Symbol("k")), sin(Symbol("i"))), list(Symbol("i"), Integer(1), Symbol("j"))), MatrixSymbol("Y", Symbol("k"), Symbol("k"))); doit(v_expr)})), "Sum(ArrayTensorProduct(X^sin(_i), Y), (_i, 1, j))")
  expect_equal(.bat_fmt(local({v_X <- MatrixSymbol("X", Symbol("k"), Symbol("k")); v_i <- Symbol("i"); v_Y <- MatrixSymbol("Y", Symbol("k"), Symbol("k")); v_j <- Symbol("j"); ArraySum(ArrayTensorProduct((v_X ^ sin(v_i)), v_Y), list(v_i, 1, v_j))})), "Sum(ArrayTensorProduct(X^sin(i), Y), (i, 1, j))")
  expect_equal(.bat_fmt(local({v_expr <- ArrayTensorProduct(ArraySum(MatPow(MatrixSymbol("X", Symbol("k"), Symbol("k")), sin(Symbol("i"))), list(Symbol("i"), Integer(1), Symbol("j"))), MatMul(Symbol("i"), MatrixSymbol("Y", Symbol("k"), Symbol("k")))); doit(v_expr)})), "Sum(ArrayTensorProduct(i, X^sin(_i), Y), (_i, 1, j))")
  expect_equal(.bat_fmt(local({v_i <- Symbol("i"); v_X <- MatrixSymbol("X", Symbol("k"), Symbol("k")); v_m <- Symbol("m"); v_Y <- MatrixSymbol("Y", Symbol("k"), Symbol("k")); v_j <- Symbol("j"); ArraySum(ArrayTensorProduct(v_i, (v_X ^ sin(v_m)), v_Y), list(v_m, 1, v_j))})), "Sum(ArrayTensorProduct(i, X^sin(m), Y), (m, 1, j))")
  expect_equal(.bat_fmt(local({v_expr <- ArrayContraction(ArraySum(MatrixSymbol("X", Symbol("k"), Symbol("k")), list(Symbol("i"), Integer(0), Symbol("j"))), Tuple(Integer(0), Integer(1))); doit(v_expr)})), "ArrayContraction((j + 1)*X, (0, 1))")
  expect_equal(.bat_fmt(local({v_j <- Symbol("j"); v_X <- MatrixSymbol("X", Symbol("k"), Symbol("k")); ArrayContraction(((v_j + 1) * v_X), list(0, 1))})), "ArrayContraction((j + 1)*X, (0, 1))")
  expect_equal(.bat_fmt(local({v_expr <- ArrayContraction(ArraySum(MatrixSymbol("T", Integer(3), Integer(3)), list(Symbol("i"), Integer(1), Symbol("j"))), Tuple(Integer(0), Integer(1))); doit(v_expr)})), "ArrayContraction(j*T, (0, 1))")
  expect_equal(.bat_fmt(local({v_j <- Symbol("j"); v_T <- MatrixSymbol("T", Integer(3), Integer(3)); ArrayContraction((v_j * v_T), list(0, 1))})), "ArrayContraction(j*T, (0, 1))")
  expect_equal(.bat_fmt(local({v_expr <- ArrayContraction(ArraySum(MatMul(sin(Symbol("i")), MatrixSymbol("T", Integer(3), Integer(3))), list(Symbol("i"), Integer(1), Symbol("j"))), Tuple(Integer(0), Integer(1))); doit(v_expr)})), "Sum(ArrayContraction(sin(i)*T, (0, 1)), (i, 1, j))")
  expect_equal(.bat_fmt(local({v_T <- MatrixSymbol("T", Integer(3), Integer(3)); v_i <- Symbol("i"); v_j <- Symbol("j"); ArraySum(ArrayContraction((v_T * sin(v_i)), list(0, 1)), list(v_i, 1, v_j))})), "Sum(ArrayContraction(sin(i)*T, (0, 1)), (i, 1, j))")
})

