  expect_equal(.bat_fmt(local({v_s2 <- ArraySum(ArrayTensorProduct((Symbol("i")*Symbol("j")), MatrixSymbol("X", Integer(2), Integer(2))), list(Symbol("i"), Integer(0), Integer(2)), list(Symbol("j"), Integer(1), Integer(2))); Array(as_explicit(v_s2))})), "[[9*X[0, 0], 9*X[0, 1]], [9*X[1, 0], 9*X[1, 1]]]")
