test_that("test_convert_array_to_indexed: test_convert_array_to_indexed_main matches SymPy", {
  expect_equal(.bat_fmt(local({v_A <- ArraySymbol(Symbol("A"), Tuple(Integer(3), Integer(3), Integer(3))); v_i <- Symbol("i"); v_j <- Symbol("j"); v_k <- Symbol("k"); convert_array_to_indexed(v_A, list(v_i, v_j, v_k))})), "A[i, j, k]")
  expect_equal(.bat_fmt(local({v_A <- ArraySymbol(Symbol("A"), Tuple(Integer(3), Integer(3), Integer(3))); v_i <- Symbol("i"); v_j <- Symbol("j"); v_k <- Symbol("k"); pyitem(v_A, v_i, v_j, v_k)})), "A[i, j, k]")
  expect_equal(.bat_fmt(local({v_conv <- (ArrayElement(ArraySymbol(Symbol("A"), Tuple(Integer(3), Integer(3), Integer(3))), Tuple(Symbol("i"), Symbol("j"), Symbol("k")))*ArrayElement(ArraySymbol(Symbol("B"), Tuple(Integer(3), Integer(3))), Tuple(Symbol("l"), Symbol("m")))*ArrayElement(ArraySymbol(Symbol("C"), Tuple(Integer(3), Integer(3))), Tuple(Symbol("n"), Symbol("o")))); v_conv})), "A[i, j, k]*B[l, m]*C[n, o]")
  expect_equal(.bat_fmt(local({v_A <- ArraySymbol(Symbol("A"), Tuple(Integer(3), Integer(3), Integer(3))); v_i <- Symbol("i"); v_j <- Symbol("j"); v_k <- Symbol("k"); v_B <- ArraySymbol(Symbol("B"), Tuple(Integer(3), Integer(3))); v_l <- Symbol("l"); v_m <- Symbol("m"); v_C <- ArraySymbol(Symbol("C"), Tuple(Integer(3), Integer(3))); v_n <- Symbol("n"); v_o <- Symbol("o"); ((pyitem(v_A, v_i, v_j, v_k) * pyitem(v_B, v_l, v_m)) * pyitem(v_C, v_n, v_o))})), "A[i, j, k]*B[l, m]*C[n, o]")
  expect_equal(.bat_fmt(local({v_conv <- (ArrayElement(ArraySymbol(Symbol("A"), Tuple(Integer(3), Integer(3), Integer(3))), Tuple(Symbol("i"), Symbol("j"), Symbol("k")))*ArrayElement(ArraySymbol(Symbol("B"), Tuple(Integer(3), Integer(3))), Tuple(Symbol("l"), Symbol("m")))*ArrayElement(ArraySymbol(Symbol("C"), Tuple(Integer(3), Integer(3))), Tuple(Symbol("n"), Symbol("o")))); v_i <- Symbol("i"); v_j <- Symbol("j"); v_k <- Symbol("k"); v_l <- Symbol("l"); v_m <- Symbol("m"); v_n <- Symbol("n"); v_o <- Symbol("o"); convert_indexed_to_array(v_conv, list(v_i, v_j, v_k, v_l, v_m, v_n, v_o))})), "ArrayTensorProduct(A, B, C)")
  expect_equal(.bat_fmt(local({v_expr <- ArrayTensorProduct(ArraySymbol(Symbol("A"), Tuple(Integer(3), Integer(3), Integer(3))), ArraySymbol(Symbol("B"), Tuple(Integer(3), Integer(3))), ArraySymbol(Symbol("C"), Tuple(Integer(3), Integer(3)))); v_expr})), "ArrayTensorProduct(A, B, C)")
  expect_equal(.bat_fmt(local({v_expr <- ArrayContraction(ArraySymbol(Symbol("A"), Tuple(Integer(3), Integer(3), Integer(3))), Tuple(Integer(0), Integer(2))); v_i <- Symbol("i"); convert_array_to_indexed(v_expr, list(v_i))})), "Sum(A[_d0, i, _d0], (_d0, 0, 2))")
  expect_equal(.bat_fmt(local({.d1 <- Dummy("d_"); v_A <- ArraySymbol(Symbol("A"), Tuple(Integer(3), Integer(3), Integer(3))); v_d_ <- .d1; v_i <- Symbol("i"); Sum(pyitem(v_A, v_d_, v_i, v_d_), list(v_d_, 0, 2))})), "Sum(A[_d_, i, _d_], (_d_, 0, 2))")
