  expect_equal(.bat_fmt(local({v_expr <- Reshape(ArraySymbol(Symbol("X"), Tuple(Integer(30))), Tuple(Integer(2), Integer(3), Integer(5))); v_i <- Symbol("i"); v_j <- Symbol("j"); v_k <- Symbol("k"); convert_array_to_indexed(v_expr, list(v_i, v_j, v_k))})), "X[15*i + 5*j + k]")
