test_that("test_convert_array_to_matrix: test_arrayexpr_convert_array_to_matrix matches SymPy", {
  expect_equal(.bat_fmt(local({v_cg <- ArrayContraction(MatrixSymbol("M", Symbol("k"), Symbol("k")), Tuple(Integer(0), Integer(1))); convert_array_to_matrix(v_cg)})), "Trace(M)")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); Trace(v_M)})), "Trace(M)")
  expect_equal(.bat_fmt(local({v_cg <- ArrayContraction(ArrayTensorProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(1)), Tuple(Integer(2), Integer(3))); convert_array_to_matrix(v_cg)})), "Trace(M)*Trace(N)")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); (Trace(v_M) * Trace(v_N))})), "Trace(M)*Trace(N)")
  expect_equal(.bat_fmt(local({v_cg <- ArrayContraction(ArrayTensorProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(3)), Tuple(Integer(1), Integer(2))); convert_array_to_matrix(v_cg)})), "Trace(M*N)")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); Trace((v_M * v_N))})), "Trace(M*N)")
  expect_equal(.bat_fmt(local({v_cg <- ArrayContraction(ArrayTensorProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(2)), Tuple(Integer(1), Integer(3))); convert_array_to_matrix(v_cg)})), "Trace(M*N.T)")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); Trace((v_M * t(v_N)))})), "Trace(M*N.T)")
  expect_equal(.bat_fmt(local({v_cg <- ArrayContraction(ArrayTensorProduct(MatrixSymbol("N", Symbol("k"), Symbol("k")), MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("P", Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(3)), Tuple(Integer(1), Integer(4))); convert_array_to_matrix(v_cg)})), "M*N*P")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); v_P <- MatrixSymbol("P", Symbol("k"), Symbol("k")); ((v_M * v_N) * v_P)})), "M*N*P")
  expect_equal(.bat_fmt(local({v_cg <- ArrayContraction(ArrayTensorProduct(MatrixSymbol("N", Symbol("k"), Symbol("k")), MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("P", Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(4)), Tuple(Integer(1), Integer(3))); convert_array_to_matrix(v_cg)})), "M*N.T*P")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); v_P <- MatrixSymbol("P", Symbol("k"), Symbol("k")); ((v_M * t(v_N)) * v_P)})), "M*N.T*P")
  expect_equal(.bat_fmt(local({v_cg <- ArrayContraction(ArrayTensorProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k")), MatrixSymbol("P", Symbol("k"), Symbol("k")), MatrixSymbol("Q", Symbol("k"), Symbol("k"))), Tuple(Integer(1), Integer(2)), Tuple(Integer(5), Integer(6))); convert_array_to_matrix(v_cg)})), "ArrayTensorProduct(M*N, P*Q)")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); v_P <- MatrixSymbol("P", Symbol("k"), Symbol("k")); v_Q <- MatrixSymbol("Q", Symbol("k"), Symbol("k")); symcompR:::.array_tensor_product((v_M * v_N), (v_P * v_Q))})), "ArrayTensorProduct(M*N, P*Q)")
  expect_equal(.bat_fmt(local({v_cg <- ArrayContraction(ArrayTensorProduct(Integer(-2), MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), Tuple(Integer(1), Integer(2))); convert_array_to_matrix(v_cg)})), "-2*M*N")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); (((-2) * v_M) * v_N)})), "-2*M*N")
  expect_equal(.bat_fmt(local({v_cg <- PermuteDims(ArrayTensorProduct(MatrixSymbol("a", Symbol("k"), Integer(1)), ArrayAdd(ArrayContraction(ArrayTensorProduct(MatrixSymbol("b", Symbol("k"), Integer(1)), MatrixSymbol("c", Symbol("k"), Integer(1))), Tuple(Integer(0), Integer(2))), ArrayContraction(ArrayTensorProduct(MatrixSymbol("c", Symbol("k"), Integer(1)), MatrixSymbol("b", Symbol("k"), Integer(1))), Tuple(Integer(0), Integer(2))))), Permutation(c(0, 1, 3, 2))); convert_array_to_matrix(v_cg)})), "a*(b.T*c + c.T*b)")
  expect_equal(.bat_fmt(local({v_a <- MatrixSymbol("a", Symbol("k"), Integer(1)); v_b <- MatrixSymbol("b", Symbol("k"), Integer(1)); v_c <- MatrixSymbol("c", Symbol("k"), Integer(1)); (v_a * ((t(v_b) * v_c) + (t(v_c) * v_b)))})), "a*(b.T*c + c.T*b)")
  expect_equal(.bat_fmt(local({v_za <- ZeroArray(Symbol("m"), Symbol("n")); convert_array_to_matrix(v_za)})), "0")
  expect_equal(.bat_fmt(local({v_m <- Symbol("m"); v_n <- Symbol("n"); ZeroMatrix(v_m, v_n)})), "0")
  expect_equal(.bat_fmt(local({v_cg <- ArrayTensorProduct(Integer(3), MatrixSymbol("M", Symbol("k"), Symbol("k"))); convert_array_to_matrix(v_cg)})), "3*M")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); (3 * v_M)})), "3*M")
  expect_equal(.bat_fmt(local({v_expr <- ArrayContraction(ArrayTensorProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k")), MatrixSymbol("P", Symbol("k"), Symbol("k")), MatrixSymbol("Q", Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(2)), Tuple(Integer(1), Integer(4), Integer(6))); convert_array_to_matrix(v_expr)})), "ArrayContraction(ArrayTensorProduct(M.T*N, P, Q), (0, 2, 4))")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); v_P <- MatrixSymbol("P", Symbol("k"), Symbol("k")); v_Q <- MatrixSymbol("Q", Symbol("k"), Symbol("k")); symcompR:::.array_contraction(symcompR:::.array_tensor_product((t(v_M) * v_N), v_P, v_Q), list(0, 2, 4))})), "ArrayContraction(ArrayTensorProduct(M.T*N, P, Q), (0, 2, 4))")
  expect_equal(.bat_fmt(local({v_cg <- PermuteDims(ArrayContraction(ArrayTensorProduct(OneArray(Integer(1)), MatrixSymbol("x", Symbol("k"), Integer(1)), OneArray(Integer(1)), DiagMatrix(Identity(Integer(1)))), Tuple(Integer(0), Integer(5))), Permutation(c(0, 2, 3, 1))); convert_array_to_matrix(v_cg)})), "x")
  expect_equal(.bat_fmt(local({v_expr <- ArrayAdd(MatrixSymbol("M", Symbol("k"), Symbol("k")), PermuteDims(MatrixSymbol("M", Symbol("k"), Symbol("k")), Permutation(c(1, 0)))); convert_array_to_matrix(v_expr)})), "M + M.T")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); (v_M + Transpose(v_M))})), "M + M.T")
})

