  expect_equal(.bat_fmt(local({v_X4 <- MatrixSymbol("X4", Integer(4), Integer(1)); v_X1 <- MatrixSymbol("X1", Integer(1), Integer(1)); list((v_X4 * (v_X1 ^ 2)), list(0, 1, 4, 5))})), "[X4*X1^2, [0, 1, 4, 5]]")
  expect_equal(.bat_fmt(local({v_expr <- ArrayTensorProduct(MatrixSymbol("X1", Integer(1), Integer(1)), MatrixSymbol("X4", Integer(4), Integer(1)), MatrixSymbol("X4", Integer(4), Integer(1))); symcompR:::.remove_trivial_dims(v_expr)})), "[X4*X1*X4.T, [0, 1, 3, 5]]")
  expect_equal(.bat_fmt(local({v_X4 <- MatrixSymbol("X4", Integer(4), Integer(1)); v_X1 <- MatrixSymbol("X1", Integer(1), Integer(1)); list(((v_X4 * v_X1) * t(v_X4)), list(0, 1, 3, 5))})), "[X4*X1*X4.T, [0, 1, 3, 5]]")
  expect_equal(.bat_fmt(local({v_expr <- ArrayTensorProduct(MatrixSymbol("X1", Integer(1), Integer(1)), MatrixSymbol("X4", Integer(4), Integer(1)), MatrixSymbol("X4", Integer(4), Integer(1)), MatrixSymbol("X1", Integer(1), Integer(1))); symcompR:::.remove_trivial_dims(v_expr)})), "[X4*X1^2*X4.T, [0, 1, 3, 5, 6, 7]]")
  expect_equal(.bat_fmt(local({v_X4 <- MatrixSymbol("X4", Integer(4), Integer(1)); v_X1 <- MatrixSymbol("X1", Integer(1), Integer(1)); list(((v_X4 * (v_X1 ^ 2)) * t(v_X4)), list(0, 1, 3, 5, 6, 7))})), "[X4*X1^2*X4.T, [0, 1, 3, 5, 6, 7]]")
  expect_equal(.bat_fmt(local({v_expr <- ArrayTensorProduct(MatrixSymbol("X4", Integer(4), Integer(1)), ArrayAdd(ArrayTensorProduct(MatrixSymbol("X4", Integer(4), Integer(1)), Identity(Integer(1))), PermuteDims(ArrayTensorProduct(Identity(Integer(1)), MatrixSymbol("X4", Integer(4), Integer(1))), Permutation(c(2, 3, 0, 1))))); symcompR:::.remove_trivial_dims(v_expr)})), "[2*X4*X4.T, [1, 3, 4, 5]]")
  expect_equal(.bat_fmt(local({v_X4 <- MatrixSymbol("X4", Integer(4), Integer(1)); list(((2 * v_X4) * t(v_X4)), list(1, 3, 4, 5))})), "[2*X4*X4.T, [1, 3, 4, 5]]")
  expect_equal(.bat_fmt(local({.d1 <- Dummy("d"); v_expr <- ArrayDiagonal(ArrayTensorProduct(ElementwiseApplyFunction(Lambda(.d1, exp(.d1)), MatrixSymbol("X1", Integer(1), Integer(1))), MatrixSymbol("X1", Integer(1), Integer(1)), MatrixSymbol("X4", Integer(4), Integer(1)), MatrixSymbol("X1", Integer(1), Integer(1))), Tuple(Integer(0), Integer(2), Integer(6)), Tuple(Integer(1), Integer(3), Integer(7))); symcompR:::.remove_trivial_dims(v_expr)})), "[exp(X1[0, 0])*X4*X1^2, [2, 3]]")
  expect_equal(.bat_fmt(local({v_X1 <- MatrixSymbol("X1", Integer(1), Integer(1)); v_X4 <- MatrixSymbol("X4", Integer(4), Integer(1)); list(((exp(pyitem(v_X1, 0, 0)) * v_X4) * (v_X1 ^ 2)), list(2, 3))})), "[exp(X1[0, 0])*X4*X1^2, [2, 3]]")
})

