test_that("test_convert_array_to_matrix: test_arrayexpr_convert_array_to_matrix_support_function matches SymPy", {
  expect_equal(.bat_fmt(local({v_k <- Symbol("k"); symcompR:::.support_function_tp1_recognize(list(), list((2 * v_k)))})), "2*k")
  expect_equal(.bat_fmt(local({v_k <- Symbol("k"); (2 * v_k)})), "2*k")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_k <- Symbol("k"); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); symcompR:::.support_function_tp1_recognize(list(list(1, 2)), list(v_A, (2 * v_k), v_B, 3))})), "(6*k)*A*B")
  expect_equal(.bat_fmt(local({v_k <- Symbol("k"); v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); (((6 * v_k) * v_A) * v_B)})), "(6*k)*A*B")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); symcompR:::.support_function_tp1_recognize(list(list(0, 3), list(1, 2)), list(v_A, v_B))})), "Trace(A*B)")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); Trace((v_A * v_B))})), "Trace(A*B)")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); symcompR:::.support_function_tp1_recognize(list(list(1, 2)), list(v_A, v_B))})), "A*B")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); (v_A * v_B)})), "A*B")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); symcompR:::.support_function_tp1_recognize(list(list(0, 2)), list(v_A, v_B))})), "A.T*B")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); (t(v_A) * v_B)})), "A.T*B")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); symcompR:::.support_function_tp1_recognize(list(list(1, 3)), list(v_A, v_B))})), "A*B.T")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); (v_A * t(v_B))})), "A*B.T")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); symcompR:::.support_function_tp1_recognize(list(list(0, 3)), list(v_A, v_B))})), "A.T*B.T")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); v_C <- MatrixSymbol("C", Symbol("k"), Symbol("k")); v_D <- MatrixSymbol("D", Symbol("k"), Symbol("k")); symcompR:::.support_function_tp1_recognize(list(list(1, 2), list(5, 6)), list(v_A, v_B, v_C, v_D))})), "ArrayTensorProduct(A*B, C*D)")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); v_C <- MatrixSymbol("C", Symbol("k"), Symbol("k")); v_D <- MatrixSymbol("D", Symbol("k"), Symbol("k")); symcompR:::.array_tensor_product((v_A * v_B), (v_C * v_D))})), "ArrayTensorProduct(A*B, C*D)")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); v_C <- MatrixSymbol("C", Symbol("k"), Symbol("k")); v_D <- MatrixSymbol("D", Symbol("k"), Symbol("k")); symcompR:::.support_function_tp1_recognize(list(list(1, 4), list(3, 6)), list(v_A, v_B, v_C, v_D))})), "PermuteDims(ArrayTensorProduct(A*C, B*D), (3)(1 2))")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_C <- MatrixSymbol("C", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); v_D <- MatrixSymbol("D", Symbol("k"), Symbol("k")); PermuteDims(symcompR:::.array_tensor_product((v_A * v_C), (v_B * v_D)), list(0, 2, 1, 3))})), "PermuteDims(ArrayTensorProduct(A*C, B*D), (3)(1 2))")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); v_C <- MatrixSymbol("C", Symbol("k"), Symbol("k")); symcompR:::.support_function_tp1_recognize(list(list(0, 3), list(1, 4)), list(v_A, v_B, v_C))})), "B*A*C")
