  expect_equal(.bat_fmt(local({v_X <- MatrixSymbol("X", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); v_Y <- MatrixSymbol("Y", Symbol("k"), Symbol("k")); v_C <- MatrixSymbol("C", Symbol("k"), Symbol("k")); v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_D <- MatrixSymbol("D", Symbol("k"), Symbol("k")); PermuteDims(symcompR:::.array_tensor_product((v_X * t(v_B)), (v_Y * v_C), (t(v_A) * t(v_D))), list(0, 2, 4, 1, 3, 5))})), "PermuteDims(ArrayTensorProduct(X*B.T, Y*C, A.T*D.T), (5)(1 2 4 3))")
