  expect_equal(.bat_fmt(local({v_X <- MatrixSymbol("X", Symbol("k"), Symbol("k")); v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); v_C <- MatrixSymbol("C", Symbol("k"), Symbol("k")); v_D <- MatrixSymbol("D", Symbol("k"), Symbol("k")); ((((v_X * v_A) * v_B) * v_C) * v_D)})), "X*A*B*C*D")
