  expect_equal(.bat_fmt(local({v_X <- MatrixSymbol("X", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); v_Y <- MatrixSymbol("Y", Symbol("k"), Symbol("k")); v_C <- MatrixSymbol("C", Symbol("k"), Symbol("k")); v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_D <- MatrixSymbol("D", Symbol("k"), Symbol("k")); PermuteDims(symcompR:::.array_tensor_product((v_X * v_B), (v_Y * v_C), (v_A * v_D)), list(0, 2, 4, 1, 3, 5))})), "PermuteDims(ArrayTensorProduct(X*B, Y*C, A*D), (5)(1 2 4 3))")
  expect_equal(.bat_fmt(local({v_X <- MatrixSymbol("X", Symbol("k"), Symbol("k")); v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); v_C <- MatrixSymbol("C", Symbol("k"), Symbol("k")); v_D <- MatrixSymbol("D", Symbol("k"), Symbol("k")); symcompR:::.support_function_tp1_recognize(list(list(0, 4), list(1, 7), list(2, 5), list(3, 8)), list(v_X, v_A, v_B, v_C, v_D))})), "C*X.T*B*A*D")
