test_that("test_convert_array_to_matrix: test_convert_array_to_hadamard_products matches SymPy", {
  expect_equal(.bat_fmt(local({v_ret <- HadamardProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))); v_ret})), "HadamardProduct(M, N)")
  expect_equal(.bat_fmt(local({v_expr <- HadamardProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))); v_expr})), "HadamardProduct(M, N)")
  expect_equal(.bat_fmt(local({v_ret <- MatMul(HadamardProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), MatrixSymbol("P", Symbol("k"), Symbol("k"))); v_ret})), "(HadamardProduct(M, N))*P")
  expect_equal(.bat_fmt(local({v_expr <- MatMul(HadamardProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), MatrixSymbol("P", Symbol("k"), Symbol("k"))); v_expr})), "(HadamardProduct(M, N))*P")
  expect_equal(.bat_fmt(local({v_ret <- MatMul(MatrixSymbol("Q", Symbol("k"), Symbol("k")), HadamardProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), MatrixSymbol("P", Symbol("k"), Symbol("k"))); v_ret})), "Q*(HadamardProduct(M, N))*P")
  expect_equal(.bat_fmt(local({v_expr <- MatMul(MatrixSymbol("Q", Symbol("k"), Symbol("k")), HadamardProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), MatrixSymbol("P", Symbol("k"), Symbol("k"))); v_expr})), "Q*(HadamardProduct(M, N))*P")
  expect_equal(.bat_fmt(local({v_ret <- MatMul(MatrixSymbol("Q", Symbol("k"), Symbol("k")), HadamardProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), Transpose(MatrixSymbol("N", Symbol("k"), Symbol("k")))), MatrixSymbol("P", Symbol("k"), Symbol("k"))); v_ret})), "Q*(HadamardProduct(M, N.T))*P")
  expect_equal(.bat_fmt(local({v_expr <- MatMul(MatrixSymbol("Q", Symbol("k"), Symbol("k")), HadamardProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), Transpose(MatrixSymbol("N", Symbol("k"), Symbol("k")))), MatrixSymbol("P", Symbol("k"), Symbol("k"))); v_expr})), "Q*(HadamardProduct(M, N.T))*P")
  expect_equal(.bat_fmt(local({v_expr <- MatMul(HadamardProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), HadamardProduct(MatrixSymbol("P", Symbol("k"), Symbol("k")), MatrixSymbol("Q", Symbol("k"), Symbol("k")))); v_expr})), "(HadamardProduct(M, N))*(HadamardProduct(P, Q))")
  expect_equal(.bat_fmt(local({v_ret <- MatMul(HadamardProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), HadamardProduct(MatrixSymbol("P", Symbol("k"), Symbol("k")), MatrixSymbol("Q", Symbol("k"), Symbol("k")))); v_ret})), "(HadamardProduct(M, N))*(HadamardProduct(P, Q))")
  expect_equal(.bat_fmt(local({v_expr <- MatMul(Transpose(MatrixSymbol("P", Symbol("k"), Symbol("k"))), HadamardProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), HadamardProduct(MatrixSymbol("P", Symbol("k"), Symbol("k")), MatrixSymbol("Q", Symbol("k"), Symbol("k")))); v_expr})), "P.T*(HadamardProduct(M, N))*(HadamardProduct(P, Q))")
  expect_equal(.bat_fmt(local({v_ret <- MatMul(Transpose(MatrixSymbol("P", Symbol("k"), Symbol("k"))), HadamardProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), HadamardProduct(MatrixSymbol("P", Symbol("k"), Symbol("k")), MatrixSymbol("Q", Symbol("k"), Symbol("k")))); v_ret})), "P.T*(HadamardProduct(M, N))*(HadamardProduct(P, Q))")
  expect_equal(.bat_fmt(local({v_expected <- PermuteDims(ArrayDiagonal(ArrayTensorProduct(HadamardProduct(Transpose(MatrixSymbol("M", Symbol("k"), Symbol("k"))), Transpose(MatrixSymbol("N", Symbol("k"), Symbol("k")))), MatrixSymbol("Q", Symbol("k"), Symbol("k"))), Tuple(Integer(1), Integer(2))), Permutation(c(1, 0, 2))); v_expected})), "PermuteDims(ArrayDiagonal(ArrayTensorProduct(HadamardProduct(M.T, N.T), Q), (1, 2)), (2)(0 1))")
  expect_equal(.bat_fmt(local({v_ret <- PermuteDims(ArrayDiagonal(ArrayTensorProduct(HadamardProduct(Transpose(MatrixSymbol("M", Symbol("k"), Symbol("k"))), Transpose(MatrixSymbol("N", Symbol("k"), Symbol("k")))), MatrixSymbol("Q", Symbol("k"), Symbol("k"))), Tuple(Integer(1), Integer(2))), Permutation(c(1, 0, 2))); v_ret})), "PermuteDims(ArrayDiagonal(ArrayTensorProduct(HadamardProduct(M.T, N.T), Q), (1, 2)), (2)(0 1))")
  expect_equal(.bat_fmt(local({v_ret <- ArrayDiagonal(ArrayTensorProduct(HadamardProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), MatrixSymbol("Q", Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(2))); v_ret})), "ArrayDiagonal(ArrayTensorProduct(HadamardProduct(M, N), Q), (0, 2))")
  expect_equal(.bat_fmt(local({v_cg <- ArrayDiagonal(ArrayTensorProduct(HadamardProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), MatrixSymbol("Q", Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(2))); v_cg})), "ArrayDiagonal(ArrayTensorProduct(HadamardProduct(M, N), Q), (0, 2))")
  expect_equal(.bat_fmt(local({v_ret <- Trace(HadamardProduct(Transpose(MatrixSymbol("M", Symbol("k"), Symbol("k"))), Transpose(MatrixSymbol("N", Symbol("k"), Symbol("k"))))); v_ret})), "Trace(HadamardProduct(M.T, N.T))")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); Trace(HadamardProduct(t(v_M), t(v_N)))})), "Trace(HadamardProduct(M.T, N.T))")
  expect_equal(.bat_fmt(local({v_ret <- Trace(MatMul(HadamardProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), MatrixSymbol("A", Symbol("k"), Symbol("k")))); v_ret})), "Trace((HadamardProduct(M, N))*A)")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); Trace((HadamardProduct(v_M, v_N) * v_A))})), "Trace((HadamardProduct(M, N))*A)")
  expect_equal(.bat_fmt(local({v_ret <- Trace(MatMul(HadamardProduct(MatrixSymbol("N", Symbol("k"), Symbol("k")), Transpose(MatrixSymbol("M", Symbol("k"), Symbol("k")))), MatrixSymbol("A", Symbol("k"), Symbol("k")))); v_ret})), "Trace((HadamardProduct(N, M.T))*A)")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); Trace((HadamardProduct(t(v_M), v_N) * v_A))})), "Trace((HadamardProduct(N, M.T))*A)")
  expect_equal(.bat_fmt(local({v_ret <- ArrayDiagonal(ArrayTensorProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(1), Integer(2), Integer(3))); v_ret})), "ArrayDiagonal(ArrayTensorProduct(M, N), (0, 1, 2, 3))")
  expect_equal(.bat_fmt(local({v_cg <- ArrayDiagonal(ArrayTensorProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(1), Integer(2), Integer(3))); v_cg})), "ArrayDiagonal(ArrayTensorProduct(M, N), (0, 1, 2, 3))")
  expect_equal(.bat_fmt(local({v_ret <- ArrayDiagonal(MatrixSymbol("A", Symbol("k"), Symbol("k")), Tuple(Integer(0), Integer(1))); v_ret})), "ArrayDiagonal(A, (0, 1))")
  expect_equal(.bat_fmt(local({v_cg <- ArrayDiagonal(MatrixSymbol("A", Symbol("k"), Symbol("k")), Tuple(Integer(0), Integer(1))); v_cg})), "ArrayDiagonal(A, (0, 1))")
  expect_equal(.bat_fmt(local({v_cg <- ArrayDiagonal(ArrayTensorProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k")), MatrixSymbol("P", Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(2), Integer(4)), Tuple(Integer(1), Integer(3), Integer(5))); convert_array_to_matrix(v_cg)})), "HadamardProduct(M, N, P)")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); v_P <- MatrixSymbol("P", Symbol("k"), Symbol("k")); HadamardProduct(v_M, v_N, v_P)})), "HadamardProduct(M, N, P)")
  expect_equal(.bat_fmt(local({v_cg <- ArrayDiagonal(ArrayTensorProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k")), MatrixSymbol("P", Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(3), Integer(4)), Tuple(Integer(1), Integer(2), Integer(5))); convert_array_to_matrix(v_cg)})), "HadamardProduct(M, P, N.T)")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_P <- MatrixSymbol("P", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); HadamardProduct(v_M, v_P, t(v_N))})), "HadamardProduct(M, P, N.T)")
  expect_equal(.bat_fmt(local({v_cg <- ArrayDiagonal(ArrayTensorProduct(Identity(Symbol("k")), Identity(Integer(1)), MatrixSymbol("x", Symbol("k"), Integer(1))), Tuple(Integer(1), Integer(4)), Tuple(Integer(3), Integer(5))); convert_array_to_matrix(v_cg)})), "DiagMatrix(x)")
  expect_equal(.bat_fmt(local({v_cg <- ArrayTensorProduct(MatrixSymbol("X1", Integer(1), Integer(1)), MatrixSymbol("X4", Integer(4), Integer(1))); convert_array_to_matrix(v_cg)})), "X4*X1")
  expect_equal(.bat_fmt(local({v_X4 <- MatrixSymbol("X4", Integer(4), Integer(1)); v_X1 <- MatrixSymbol("X1", Integer(1), Integer(1)); (v_X4 * v_X1)})), "X4*X1")
  expect_equal(.bat_fmt(local({v_cg <- ArrayTensorProduct(MatrixSymbol("X4", Integer(4), Integer(1)), ArrayAdd(ArrayTensorProduct(MatrixSymbol("X4", Integer(4), Integer(1)), Identity(Integer(1))), PermuteDims(ArrayTensorProduct(Identity(Integer(1)), MatrixSymbol("X4", Integer(4), Integer(1))), Permutation(c(2, 3, 0, 1))))); convert_array_to_matrix(v_cg)})), "2*X4*X4.T")
  expect_equal(.bat_fmt(local({v_X4 <- MatrixSymbol("X4", Integer(4), Integer(1)); ((2 * v_X4) * t(v_X4))})), "2*X4*X4.T")
  expect_equal(.bat_fmt(local({.d1 <- Dummy("d"); v_cg <- ArrayDiagonal(ArrayTensorProduct(ElementwiseApplyFunction(Lambda(.d1, exp(.d1)), MatrixSymbol("X1", Integer(1), Integer(1))), MatrixSymbol("X1", Integer(1), Integer(1)), MatrixSymbol("X4", Integer(4), Integer(1)), MatrixSymbol("X1", Integer(1), Integer(1))), Tuple(Integer(0), Integer(2), Integer(6)), Tuple(Integer(1), Integer(3), Integer(7))); convert_array_to_matrix(v_cg)})), "X4*Lambda(_d, exp(_d)).(X1)*X1^2")
  expect_equal(.bat_fmt(local({v_X4 <- MatrixSymbol("X4", Integer(4), Integer(1)); v_X1 <- MatrixSymbol("X1", Integer(1), Integer(1)); ((v_X4 * applyfunc(v_X1, exp)) * (v_X1 ^ 2))})), "X4*Lambda(_d, exp(_d)).(X1)*X1^2")
})

