  expect_equal(.bat_fmt(local({.d1 <- Dummy("d"); v_expr <- ArrayElementwiseApplyFunc(Lambda(.d1, (.d1)^(Integer(2))), MatMul(Transpose(MatrixSymbol("x", Symbol("k"), Integer(1))), MatrixSymbol("y", Symbol("k"), Integer(1)))); convert_array_to_matrix(v_expr)})), "(x.T*y)^2")
  expect_equal(.bat_fmt(local({v_x <- MatrixSymbol("x", Symbol("k"), Integer(1)); v_y <- MatrixSymbol("y", Symbol("k"), Integer(1)); ((t(v_x) * v_y) ^ 2)})), "(x.T*y)^2")
  expect_equal(.bat_fmt(local({.d1 <- Dummy("d"); v_expr <- ArrayElementwiseApplyFunc(Lambda(.d1, sin(.d1)), MatrixSymbol("x", Symbol("k"), Integer(1))); convert_array_to_matrix(v_expr)})), "Lambda(_d, sin(_d)).(x)")
  expect_equal(.bat_fmt(local({v_x <- MatrixSymbol("x", Symbol("k"), Integer(1)); applyfunc(v_x, sin)})), "Lambda(_d, sin(_d)).(x)")
  expect_equal(.bat_fmt(local({.d1 <- Dummy("d"); v_expr <- ArrayElementwiseApplyFunc(Lambda(.d1, (Rational(1, 2)*(.d1)^(Rational(-1, 2)))), MatrixSymbol("x", Symbol("k"), Integer(1))); convert_array_to_matrix(v_expr)})), "(1/2)*HadamardPower(x, -1/2)")
