  expect_equal(.bat_fmt(local({.d1 <- Dummy("d"); v_expr <- ArrayElementwiseApplyFunc(Lambda(.d1, sin(.d1)), Trace(MatrixSymbol("X", Symbol("k"), Symbol("k")))); convert_array_to_matrix(v_expr)})), "sin(Trace(X))")
  expect_equal(.bat_fmt(local({v_X <- MatrixSymbol("X", Symbol("k"), Symbol("k")); sin(Trace(v_X))})), "sin(Trace(X))")
})

