  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_y <- Symbol("y"); v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); v_P <- MatrixSymbol("P", Symbol("k"), Symbol("k")); ((((v_x * v_y) * v_M) * v_N) * v_P)})), "(x*y)*M*N*P")
  expect_equal(.bat_fmt(local({v_cg <- ArrayContraction(ArrayTensorProduct(Integer(3), MatrixSymbol("M", Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(1))); convert_array_to_matrix(v_cg)})), "3*Trace(M)")
