  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); convert_array_to_matrix(symcompR:::.array_tensor_product((2 * v_M), (3 * v_N)))})), "ArrayTensorProduct(6, M, N)")
