  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); ArrayTensorProduct(5, v_M, v_N)})), "ArrayTensorProduct(5, M, N)")
  expect_equal(.bat_fmt(local({v_cg <- PermuteDims(ArrayTensorProduct(Integer(2), MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), Permutation(c(2, 3, 0, 1))); convert_array_to_matrix(v_cg)})), "ArrayTensorProduct(2, N, M)")
  expect_equal(.bat_fmt(local({v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); ArrayTensorProduct(2, v_N, v_M)})), "ArrayTensorProduct(2, N, M)")
  expect_equal(.bat_fmt(local({v_cg <- PermuteDims(ArrayContraction(ArrayTensorProduct(Integer(3), MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k")), MatrixSymbol("P", Symbol("k"), Symbol("k"))), Tuple(Integer(1), Integer(2))), Permutation(c(1, 0, 3, 2))); convert_array_to_matrix(v_cg)})), "ArrayTensorProduct(3, N.T*M.T, P.T)")
  expect_equal(.bat_fmt(local({v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_P <- MatrixSymbol("P", Symbol("k"), Symbol("k")); ArrayTensorProduct(3, (t(v_N) * t(v_M)), t(v_P))})), "ArrayTensorProduct(3, N.T*M.T, P.T)")
  expect_equal(.bat_fmt(local({v_cg <- PermuteDims(ArrayContraction(ArrayTensorProduct(Integer(3), MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k")), MatrixSymbol("P", Symbol("k"), Symbol("k"))), Tuple(Integer(1), Integer(2))), Permutation(c(2, 3, 0, 1))); convert_array_to_matrix(v_cg)})), "ArrayTensorProduct(3, P, M*N)")
  expect_equal(.bat_fmt(local({v_P <- MatrixSymbol("P", Symbol("k"), Symbol("k")); v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); ArrayTensorProduct(3, v_P, (v_M * v_N))})), "ArrayTensorProduct(3, P, M*N)")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); symcompR:::.support_function_tp1_recognize(list(list(1, 2)), list((2 * v_M), v_N))})), "2*M*N")
})

