  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); v_i <- Symbol("i"); v_k <- Symbol("k"); list(ArrayContraction(ArrayTensorProduct(v_M, v_N), list(1, 2)), list(v_i, v_k))})), "[ArrayContraction(ArrayTensorProduct(M, N), (1, 2)), [i, k]]")
