  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); v__perm1 <- Permutation(c(1, 0)); v_i <- Symbol("i"); v_j <- Symbol("j"); list(ArrayAdd(v_M, PermuteDims(v_N, v__perm1)), list(v_i, v_j))})), "[ArrayAdd(M, PermuteDims(N, (0 1))), [i, j]]")
