  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v__perm1 <- Permutation(c(1, 0)); v_i <- Symbol("i"); v_j <- Symbol("j"); list(ArrayAdd(v_M, PermuteDims(v_M, v__perm1)), list(v_i, v_j))})), "[ArrayAdd(M, PermuteDims(M, (0 1))), [i, j]]")
  expect_equal(.bat_fmt(local({.d1 <- Dummy("i_1"); .d2 <- Dummy("i_2"); v_expr <- Sum((MatrixElement(MatrixSymbol("M", Symbol("k"), Symbol("k")), Symbol("i"), .d1)*MatrixElement(MatrixSymbol("N", Symbol("k"), Symbol("k")), .d1, .d2)*MatrixElement(MatrixSymbol("P", Symbol("k"), Symbol("k")), .d2, Symbol("j"))), list(.d1, Integer(0), (Integer(-1) + Symbol("k"))), list(.d2, Integer(0), (Integer(-1) + Symbol("k")))); symcompR:::.convert_indexed_to_array(v_expr)})), "[ArrayContraction(ArrayTensorProduct(N, M, P), (0, 3), (1, 4)), [i, j]]")
