  expect_equal(.bat_fmt(local({v_ret1 <- ArrayDiagonal(ArrayTensorProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k")), MatrixSymbol("P", Symbol("k"), Symbol("k"))), Tuple(Integer(1), Integer(2)), Tuple(Integer(3), Integer(4))); v_ret1})), "ArrayDiagonal(ArrayTensorProduct(M, N, P), (1, 2), (3, 4))")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); v_P <- MatrixSymbol("P", Symbol("k"), Symbol("k")); ArrayDiagonal(ArrayTensorProduct(v_M, v_N, v_P), list(1, 2), list(3, 4))})), "ArrayDiagonal(ArrayTensorProduct(M, N, P), (1, 2), (3, 4))")
  expect_equal(.bat_fmt(local({v_expr <- (KroneckerDelta(Symbol("i"), Symbol("j"))*MatrixElement(MatrixSymbol("M", Symbol("k"), Symbol("k")), Symbol("i"), Symbol("k"))); symcompR:::.convert_indexed_to_array(v_expr)})), "[M, [{i, j}, k]]")
  expect_equal(.bat_fmt(local({v_expr <- (KroneckerDelta(Symbol("i"), Symbol("j"))*KroneckerDelta(Symbol("j"), Symbol("k"))*MatrixElement(MatrixSymbol("M", Symbol("k"), Symbol("k")), Symbol("i"), Symbol("l"))); symcompR:::.convert_indexed_to_array(v_expr)})), "[M, [{i, j, k}, l]]")
  expect_equal(.bat_fmt(local({v_expr <- (((MatrixElement(MatrixSymbol("M", Symbol("k"), Symbol("k")), Symbol("i"), Symbol("j"))*MatrixElement(MatrixSymbol("N", Symbol("k"), Symbol("k")), Symbol("k"), Symbol("l"))) + (MatrixElement(MatrixSymbol("M", Symbol("k"), Symbol("k")), Symbol("k"), Symbol("l"))*MatrixElement(MatrixSymbol("N", Symbol("k"), Symbol("k")), Symbol("i"), Symbol("j"))))*KroneckerDelta(Symbol("j"), Symbol("k"))); symcompR:::.convert_indexed_to_array(v_expr)})), "[ArrayAdd(ArrayDiagonal(ArrayTensorProduct(M, N), (1, 2)), ArrayDiagonal(ArrayTensorProduct(N, M), (1, 2))), [i, l, {j, k}]]")
  expect_equal(.bat_fmt(local({v_expr <- (((MatrixElement(MatrixSymbol("M", Symbol("k"), Symbol("k")), Symbol("i"), Symbol("j"))*MatrixElement(MatrixSymbol("N", Symbol("k"), Symbol("k")), Symbol("k"), Symbol("l"))) + (MatrixElement(MatrixSymbol("M", Symbol("k"), Symbol("k")), Symbol("k"), Symbol("l"))*MatrixElement(MatrixSymbol("N", Symbol("k"), Symbol("k")), Symbol("i"), Symbol("j"))))*KroneckerDelta(Symbol("j"), Symbol("m"))*KroneckerDelta(Symbol("k"), Symbol("m"))); symcompR:::.convert_indexed_to_array(v_expr)})), "[ArrayAdd(ArrayDiagonal(ArrayTensorProduct(M, N), (1, 2)), ArrayDiagonal(ArrayTensorProduct(N, M), (1, 2))), [i, l, {j, k, m}]]")
  expect_equal(.bat_fmt(local({v_expr <- (KroneckerDelta(Symbol("i"), Symbol("j"))*KroneckerDelta(Symbol("j"), Symbol("k"))*KroneckerDelta(Symbol("k"), Symbol("m"))*KroneckerDelta(Symbol("m"), Symbol("n"))*MatrixElement(MatrixSymbol("M", Symbol("k"), Symbol("k")), Symbol("i"), Integer(0))); symcompR:::.convert_indexed_to_array(v_expr)})), "[M, [{i, j, k, m, n}, 0]]")
  expect_equal(.bat_fmt(local({v_expr <- MatrixElement(MatrixSymbol("M", Symbol("k"), Symbol("k")), Symbol("i"), Symbol("i")); symcompR:::.convert_indexed_to_array(v_expr)})), "[ArrayDiagonal(M, (0, 1)), [i]]")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_i <- Symbol("i"); list(ArrayDiagonal(v_M, list(0, 1)), list(v_i))})), "[ArrayDiagonal(M, (0, 1)), [i]]")
})

