  expect_equal(.bat_fmt(local({v_cg <- ArrayTensorProduct(ArraySymbol(Symbol("A"), Tuple(Symbol("k"))), ArraySymbol(Symbol("B"), Tuple(Symbol("k")))); v_cg})), "ArrayTensorProduct(A, B)")
