  expect_equal(.bat_fmt(local({v_A <- ArraySymbol(Symbol("A"), Tuple(Symbol("k"))); v_B <- ArraySymbol(Symbol("B"), Tuple(Symbol("k"))); ArrayElementwiseApplyFunc(tanh, ArrayTensorProduct(v_A, v_B))})), "ArrayElementwiseApplyFunc(Lambda(_d, tanh(_d)), ArrayTensorProduct(A, B))")
