  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); (v_M + t(v_N))})), "M + N.T")
  expect_equal(.bat_fmt(local({v_p1 <- ArrayAdd(ArrayTensorProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), ArrayTensorProduct(MatrixSymbol("N", Symbol("k"), Symbol("k")), MatrixSymbol("M", Symbol("k"), Symbol("k")))); convert_array_to_matrix(v_p1)})), "ArrayAdd(ArrayTensorProduct(M, N), ArrayTensorProduct(N, M))")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); ArrayAdd(ArrayTensorProduct(v_M, v_N), ArrayTensorProduct(v_N, v_M))})), "ArrayAdd(ArrayTensorProduct(M, N), ArrayTensorProduct(N, M))")
  expect_equal(.bat_fmt(local({v_p1 <- ArrayContraction(ArrayTensorProduct(MatrixSymbol("N", Symbol("k"), Symbol("k")), MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("P", Symbol("k"), Symbol("k"))), Tuple(Integer(0), Integer(3)), Tuple(Integer(1), Integer(4))); convert_array_to_matrix(v_p1)})), "M*N*P")
  expect_equal(.bat_fmt(local({v_p1 <- ArrayContraction(ArrayTensorProduct(ArrayAdd(MatrixSymbol("P", Symbol("k"), Symbol("k")), PermuteDims(MatrixSymbol("P", Symbol("k"), Symbol("k")), Permutation(c(1, 0)))), ArrayAdd(ArrayTensorProduct(MatrixSymbol("M", Symbol("k"), Symbol("k")), MatrixSymbol("N", Symbol("k"), Symbol("k"))), ArrayTensorProduct(MatrixSymbol("N", Symbol("k"), Symbol("k")), MatrixSymbol("M", Symbol("k"), Symbol("k"))))), Tuple(Integer(0), Integer(3)), Tuple(Integer(1), Integer(4))); convert_array_to_matrix(v_p1)})), "M*P*N + M*P.T*N + N*P*M + N*P.T*M")
  expect_equal(.bat_fmt(local({v_M <- MatrixSymbol("M", Symbol("k"), Symbol("k")); v_P <- MatrixSymbol("P", Symbol("k"), Symbol("k")); v_N <- MatrixSymbol("N", Symbol("k"), Symbol("k")); (((((v_M * v_P) * v_N) + ((v_M * t(v_P)) * v_N)) + ((v_N * v_P) * v_M)) + ((v_N * t(v_P)) * v_M))})), "M*P*N + M*P.T*N + N*P*M + N*P.T*M")
})

