  expect_equal(.bat_fmt(local({v_A <- ArraySymbol(Symbol("A"), Tuple(Integer(3), Integer(3))); v_O1 <- OneArray(Integer(3)); v_B <- ArraySymbol(Symbol("B"), Tuple(Integer(3), Integer(3))); ArrayAdd(ArrayTensorProduct(v_A, v_O1), ArrayTensorProduct(v_O1, v_B))})), "ArrayAdd(ArrayTensorProduct(A, OneArray(3)), ArrayTensorProduct(OneArray(3), B))")
  expect_equal(.bat_fmt(local({v_expr <- (ArrayElement(ArraySymbol(Symbol("C"), Tuple(Symbol("d0"), Symbol("d1"))), Tuple(Symbol("i"), Symbol("j"))) + ArrayElement(ArraySymbol(Symbol("D"), Tuple(Symbol("d3"), Symbol("d1"))), Tuple(Symbol("k"), Symbol("j")))); v_i <- Symbol("i"); v_j <- Symbol("j"); v_k <- Symbol("k"); convert_indexed_to_array(v_expr, list(v_i, v_j, v_k))})), "ArrayAdd(ArrayTensorProduct(C, OneArray(d3)), PermuteDims(ArrayTensorProduct(OneArray(d0), D), (1 2)))")
  expect_equal(.bat_fmt(local({v_C <- ArraySymbol(Symbol("C"), Tuple(Symbol("d0"), Symbol("d1"))); v_d3 <- Symbol("d3"); v_d0 <- Symbol("d0"); v_D <- ArraySymbol(Symbol("D"), Tuple(Symbol("d3"), Symbol("d1"))); ArrayAdd(ArrayTensorProduct(v_C, OneArray(v_d3)), PermuteDims(ArrayTensorProduct(OneArray(v_d0), v_D), list(0, 2, 1)))})), "ArrayAdd(ArrayTensorProduct(C, OneArray(d3)), PermuteDims(ArrayTensorProduct(OneArray(d0), D), (1 2)))")
  expect_equal(.bat_fmt(local({v_X <- ArraySymbol(Symbol("X"), Tuple(Integer(5), Integer(3))); ArrayAdd(ArrayTensorProduct((-1), OneArray(5), v_X), PermuteDims(ArrayTensorProduct(v_X, OneArray(5)), list(0, 2, 1)))})), "ArrayAdd(ArrayTensorProduct(-1, OneArray(5), X), PermuteDims(ArrayTensorProduct(X, OneArray(5)), (1 2)))")
