  expect_equal(.bat_fmt(local({v_expr <- MatPow(MatrixSymbol("M", Symbol("k"), Symbol("k")), Integer(2)); convert_matrix_to_array(v_expr)})), "ArrayContraction(ArrayTensorProduct(M, M), (1, 2))")
