  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); v_k <- Symbol("k"); Reshape(PermuteDims(ArrayTensorProduct(v_A, v_B), list(0, 2, 1, 3)), list((v_k ^ 2), (v_k ^ 2)))})), "Reshape(PermuteDims(ArrayTensorProduct(A, B), (3)(1 2)), (k^2, k^2))")
