  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); v_B <- MatrixSymbol("B", Symbol("k"), Symbol("k")); v_C <- MatrixSymbol("C", Symbol("k"), Symbol("k")); v_D <- MatrixSymbol("D", Symbol("k"), Symbol("k")); v_k <- Symbol("k"); Reshape(PermuteDims(ArrayTensorProduct(v_A, v_B, v_C, v_D), list(0, 2, 4, 6, 1, 3, 5, 7)), list((v_k ^ 4), (v_k ^ 4)))})), "Reshape(PermuteDims(ArrayTensorProduct(A, B, C, D), (7)(1 2 4)(3 6 5)), (k^4, k^4))")
  expect_equal(.bat_fmt(local({.d1 <- Dummy("d"); v_cg <- ArrayElementwiseApplyFunc(Lambda(.d1, (.d1)^(Integer(-1))), ArrayContraction(MatrixSymbol("A", Symbol("k"), Symbol("k")), Tuple(Integer(0), Integer(1)))); v_cg})), "ArrayElementwiseApplyFunc(Lambda(_d, 1/_d), ArrayContraction(A, (0, 1)))")
  expect_equal(.bat_fmt(local({v_m <- Symbol("m"); v_A <- MatrixSymbol("A", Symbol("k"), Symbol("k")); ArrayElementwiseApplyFunc(Lambda(v_m, (1 / v_m)), ArrayContraction(v_A, list(0, 1)))})), "ArrayElementwiseApplyFunc(Lambda(m, 1/m), ArrayContraction(A, (0, 1)))")
