  expect_equal(.bat_fmt(local({v_X <- MatrixSymbol("X", Symbol("k"), Symbol("k")); ArrayElementwiseApplyFunc(sqrt, ArrayContraction(ArrayTensorProduct(v_X, v_X), list(0, 2), list(1, 3)))})), "ArrayElementwiseApplyFunc(Lambda(_d, sqrt(_d)), ArrayContraction(ArrayTensorProduct(X, X), (0, 2), (1, 3)))")
  expect_equal(.bat_fmt(local({v_expr <- (Symbol("i"))^(Integer(3)); convert_matrix_to_array(v_expr)})), "i^3")
