  expect_equal(.bat_fmt(local({v_expr <- MatPow(MatrixSymbol("X", Symbol("k"), Symbol("k")), sin(Integer(1))); convert_matrix_to_array(v_expr)})), "X^sin(1)")
  expect_equal(.bat_fmt(local({v_expr <- MatPow(MatrixSymbol("X", Symbol("k"), Symbol("k")), sin(Integer(1))); v_expr})), "X^sin(1)")
