test_that("test_simplification: test_array_add_collect_coefficients matches SymPy", {
  expect_equal(.bat_fmt(local({v_T <- ArrayTensorProduct(ArraySymbol(Symbol("Ra"), Tuple(Integer(2), Integer(3))), ArraySymbol(Symbol("Rb"), Tuple(Integer(3), Integer(4)))); doit(ArrayAdd(v_T, v_T))})), "ArrayTensorProduct(2, Ra, Rb)")
  expect_equal(.bat_fmt(local({v_Ra <- ArraySymbol(Symbol("Ra"), Tuple(Integer(2), Integer(3))); v_Rb <- ArraySymbol(Symbol("Rb"), Tuple(Integer(3), Integer(4))); ArrayTensorProduct(2, v_Ra, v_Rb)})), "ArrayTensorProduct(2, Ra, Rb)")
  expect_equal(.bat_fmt(local({v_Ra <- ArraySymbol(Symbol("Ra"), Tuple(Integer(2), Integer(3))); v_Rb <- ArraySymbol(Symbol("Rb"), Tuple(Integer(3), Integer(4))); doit(ArrayAdd(ArrayTensorProduct(2, v_Ra, v_Rb), ArrayTensorProduct(3, v_Ra, v_Rb)))})), "ArrayTensorProduct(5, Ra, Rb)")
  expect_equal(.bat_fmt(local({v_Ra <- ArraySymbol(Symbol("Ra"), Tuple(Integer(2), Integer(3))); v_Rb <- ArraySymbol(Symbol("Rb"), Tuple(Integer(3), Integer(4))); ArrayTensorProduct(5, v_Ra, v_Rb)})), "ArrayTensorProduct(5, Ra, Rb)")
  expect_equal(.bat_fmt(local({v_T <- ArrayTensorProduct(ArraySymbol(Symbol("Ra"), Tuple(Integer(2), Integer(3))), ArraySymbol(Symbol("Rb"), Tuple(Integer(3), Integer(4)))); v_Ra <- ArraySymbol(Symbol("Ra"), Tuple(Integer(2), Integer(3))); v_Rb <- ArraySymbol(Symbol("Rb"), Tuple(Integer(3), Integer(4))); doit(ArrayAdd(v_T, ArrayTensorProduct((-1), v_Ra, v_Rb)))})), "ZeroArray(2, 3, 3, 4)")
  expect_equal(.bat_fmt(local({ZeroArray(2, 3, 3, 4)})), "ZeroArray(2, 3, 3, 4)")
  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_Ra <- ArraySymbol(Symbol("Ra"), Tuple(Integer(2), Integer(3))); v_Rb <- ArraySymbol(Symbol("Rb"), Tuple(Integer(3), Integer(4))); v_y <- Symbol("y"); doit(ArrayAdd(ArrayTensorProduct(v_x, v_Ra, v_Rb), ArrayTensorProduct(v_y, v_Ra, v_Rb)))})), "ArrayTensorProduct(x + y, Ra, Rb)")
  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_y <- Symbol("y"); v_Ra <- ArraySymbol(Symbol("Ra"), Tuple(Integer(2), Integer(3))); v_Rb <- ArraySymbol(Symbol("Rb"), Tuple(Integer(3), Integer(4))); ArrayTensorProduct((v_x + v_y), v_Ra, v_Rb)})), "ArrayTensorProduct(x + y, Ra, Rb)")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Integer(2), Integer(2)); v_B <- MatrixSymbol("B", Integer(2), Integer(2)); doit(ArrayAdd(ArrayTensorProduct((2 * v_A), v_B), ArrayTensorProduct(3, v_A, v_B)))})), "ArrayTensorProduct(5, A, B)")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Integer(2), Integer(2)); v_B <- MatrixSymbol("B", Integer(2), Integer(2)); ArrayTensorProduct(5, v_A, v_B)})), "ArrayTensorProduct(5, A, B)")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Integer(2), Integer(2)); doit(ArrayAdd(v_A, v_A))})), "2*A")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Integer(2), Integer(2)); (2 * v_A)})), "2*A")
  expect_equal(.bat_fmt(local({v_e <- ArrayAdd(ArrayTensorProduct(ArraySymbol(Symbol("Ra"), Tuple(Integer(2), Integer(3))), ArraySymbol(Symbol("Rb"), Tuple(Integer(3), Integer(4)))), ArrayTensorProduct(ArraySymbol(Symbol("Rc"), Tuple(Integer(2), Integer(3))), ArraySymbol(Symbol("Rb"), Tuple(Integer(3), Integer(4))))); doit(v_e)})), "ArrayAdd(ArrayTensorProduct(Ra, Rb), ArrayTensorProduct(Rc, Rb))")
  expect_equal(.bat_fmt(local({v_e <- ArrayAdd(ArrayTensorProduct(ArraySymbol(Symbol("Ra"), Tuple(Integer(2), Integer(3))), ArraySymbol(Symbol("Rb"), Tuple(Integer(3), Integer(4)))), ArrayTensorProduct(ArraySymbol(Symbol("Rc"), Tuple(Integer(2), Integer(3))), ArraySymbol(Symbol("Rb"), Tuple(Integer(3), Integer(4))))); v_e})), "ArrayAdd(ArrayTensorProduct(Ra, Rb), ArrayTensorProduct(Rc, Rb))")
  expect_equal(.bat_fmt(local({v_Ra <- ArraySymbol(Symbol("Ra"), Tuple(Integer(2), Integer(3))); v_Rc <- ArraySymbol(Symbol("Rc"), Tuple(Integer(2), Integer(3))); doit(ArrayAdd((2 * v_Ra), v_Rc))})), "ArrayAdd(ArrayTensorProduct(2, Ra), Rc)")
  expect_equal(.bat_fmt(local({v_Ra <- ArraySymbol(Symbol("Ra"), Tuple(Integer(2), Integer(3))); v_Rc <- ArraySymbol(Symbol("Rc"), Tuple(Integer(2), Integer(3))); ArrayAdd(ArrayTensorProduct(2, v_Ra), v_Rc)})), "ArrayAdd(ArrayTensorProduct(2, Ra), Rc)")
})

test_that("test_simplification: test_collect_tensor_products matches SymPy", {
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Integer(2), Integer(2)); v_B <- MatrixSymbol("B", Integer(2), Integer(2)); v_C <- MatrixSymbol("C", Integer(2), Integer(2)); collect_tensor_products(ArrayAdd(ArrayTensorProduct(v_A, v_B), ArrayTensorProduct(v_A, v_C)))})), "ArrayTensorProduct(A, B + C)")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Integer(2), Integer(2)); v_B <- MatrixSymbol("B", Integer(2), Integer(2)); v_C <- MatrixSymbol("C", Integer(2), Integer(2)); ArrayTensorProduct(v_A, (v_B + v_C))})), "ArrayTensorProduct(A, B + C)")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Integer(2), Integer(2)); v_B <- MatrixSymbol("B", Integer(2), Integer(2)); v_C <- MatrixSymbol("C", Integer(2), Integer(2)); collect_tensor_products(ArrayAdd(ArrayTensorProduct(v_A, v_B), ArrayTensorProduct(v_C, v_B)))})), "ArrayTensorProduct(A + C, B)")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Integer(2), Integer(2)); v_C <- MatrixSymbol("C", Integer(2), Integer(2)); v_B <- MatrixSymbol("B", Integer(2), Integer(2)); ArrayTensorProduct((v_A + v_C), v_B)})), "ArrayTensorProduct(A + C, B)")
