test_that("test_array_derivatives: test_derivative_routing_to_array_derivative matches SymPy", {
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Integer(3), Integer(3)); v_X <- MatrixSymbol("X", Integer(3), Integer(3)); Derivative(Trace((v_A * v_X)), v_X)})), "Derivative(Trace(A*X), X)")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Integer(3), Integer(3)); v_X <- MatrixSymbol("X", Integer(3), Integer(3)); Derivative((v_A * v_X), v_X)})), "Derivative(A*X, X)")
  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_m <- Matrix(list(list(Symbol("x"), Symbol("y")), list(Symbol("z"), Symbol("t")))); Derivative(v_x, v_m, evaluate = FALSE)})), "Derivative(x, Matrix([\\n[x, y],\\n[z, t]]))")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Integer(3), Integer(3)); v_X <- MatrixSymbol("X", Integer(3), Integer(3)); doit(Derivative(Trace((v_A * v_X)), v_X))})), "A.T")
  expect_equal(.bat_fmt(local({v_X <- MatrixSymbol("X", Integer(3), Integer(3)); v_A <- MatrixSymbol("A", Integer(3), Integer(3)); diff(Trace((v_A * v_X)), v_X)})), "A.T")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Integer(3), Integer(3)); v_X <- MatrixSymbol("X", Integer(3), Integer(3)); Derivative(Trace((v_A * v_X)), v_X, evaluate = TRUE)})), "A.T")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Integer(3), Integer(3)); t(v_A)})), "A.T")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Integer(3), Integer(3)); v_X <- MatrixSymbol("X", Integer(3), Integer(3)); doit(Derivative((v_A * v_X), v_X))})), "PermuteDims(ArrayTensorProduct(A.T, I), (3)(1 2))")
  expect_equal(.bat_fmt(local({v_X <- MatrixSymbol("X", Integer(3), Integer(3)); v_A <- MatrixSymbol("A", Integer(3), Integer(3)); diff((v_A * v_X), v_X)})), "PermuteDims(ArrayTensorProduct(A.T, I), (3)(1 2))")
  expect_equal(.bat_fmt(local({v_s <- Symbol("s"); doit(Derivative(Array(list(Function("f")(v_s), v_s)), v_s))})), "[Derivative(f(s), s), 1]")
  expect_equal(.bat_fmt(local({v_s <- Symbol("s"); Array(list(diff(Function("f")(v_s), v_s), 1))})), "[Derivative(f(s), s), 1]")
  expect_equal(.bat_fmt(local({v_s <- Symbol("s"); v_t <- Symbol("t"); doit(Derivative(Array(list(list(v_s, v_t), list((v_s * v_t), (v_s ^ 2)))), v_s))})), "[[1, 0], [t, 2*s]]")
  expect_equal(.bat_fmt(local({v_t <- Symbol("t"); v_s <- Symbol("s"); Array(list(list(1, 0), list(v_t, (2 * v_s))))})), "[[1, 0], [t, 2*s]]")
  expect_equal(.bat_fmt(local({v_x <- Symbol("x"); v_y <- Symbol("y"); v_z <- Symbol("z"); v_u <- Symbol("u"); v_w <- Symbol("w"); doit(Derivative(v_x, Matrix(list(list(v_y, v_z), list(v_u, v_w)))))})), "Matrix([[0, 0], [0, 0]])")
  expect_equal(.bat_fmt(local({v_y <- Symbol("y"); v_p <- Symbol("p"); v_z <- Symbol("z"); v_q <- Symbol("q"); doit(Derivative(Matrix(list(list((v_y * v_p), (v_z + v_q)))), Matrix(list(list(v_p, v_q)))))})), "[[[[y, 0]], [[0, 1]]]]")
  expect_equal(.bat_fmt(local({v_p <- Symbol("p"); v_q <- Symbol("q"); v_y <- Symbol("y"); v_z <- Symbol("z"); diff(Matrix(list(list((v_y * v_p), (v_z + v_q)))), Matrix(list(list(v_p, v_q))))})), "[[[[y, 0]], [[0, 1]]]]")
  expect_equal(.bat_fmt(local({v_X <- MatrixSymbol("X", Integer(3), Integer(3)); doit(Derivative(Trace((v_X * v_X)), v_X, 2))})), "PermuteDims(ArrayTensorProduct(2, I, I), (1 2 3))")
  expect_equal(.bat_fmt(local({v_X <- MatrixSymbol("X", Integer(3), Integer(3)); diff(diff(Trace((v_X * v_X)), v_X), v_X)})), "PermuteDims(ArrayTensorProduct(2, I, I), (1 2 3))")
  expect_equal(.bat_fmt(local({v_v <- MatrixSymbol("v", Integer(3), Integer(1)); v_A <- MatrixSymbol("A", Integer(3), Integer(3)); doit(Derivative(((t(v_v) * v_A) * v_v), v_v, 2))})), "A + A.T")
  expect_equal(.bat_fmt(local({v_v <- MatrixSymbol("v", Integer(3), Integer(1)); v_A <- MatrixSymbol("A", Integer(3), Integer(3)); diff(diff(((t(v_v) * v_A) * v_v), v_v), v_v)})), "A + A.T")
  expect_equal(.bat_fmt(local({v_A <- MatrixSymbol("A", Integer(3), Integer(3)); (v_A + t(v_A))})), "A + A.T")
})

test_that("test_array_comprehension: test_array_comprehension matches SymPy", {
  expect_equal(.bat_fmt(local({list(list(2, 3, 4), list(4, 6, 8), list(6, 9, 12))})), "[[2, 3, 4], [4, 6, 8], [6, 9, 12]]")
  expect_equal(.bat_fmt(local({v_a <- ArrayComprehension((Symbol("i")*Symbol("j")), Tuple(Symbol("i"), Integer(1), Integer(3)), Tuple(Symbol("j"), Integer(2), Integer(4))); get_shape(v_a)})), "[3, 3]")
  expect_equal(.bat_fmt(local({Matrix(list(list(2, 3, 4), list(4, 6, 8), list(6, 9, 12)))})), "Matrix([[2, 3, 4], [4, 6, 8], [6, 9, 12]])")
  expect_equal(.bat_fmt(local({v_b <- ArrayComprehension(Symbol("i"), Tuple(Symbol("i"), Integer(1), (Integer(1) + Symbol("j")))); doit(v_b)})), "ArrayComprehension(i, (i, 1, j + 1))")
  expect_equal(.bat_fmt(local({v_a <- ArrayComprehension((Symbol("i")*Symbol("j")), Tuple(Symbol("i"), Integer(1), Integer(3)), Tuple(Symbol("j"), Integer(2), Integer(4))); doit(v_a)})), "[[2, 3, 4], [4, 6, 8], [6, 9, 12]]")
  expect_equal(.bat_fmt(local({v_j <- Symbol("j"); v_b <- ArrayComprehension(Symbol("i"), Tuple(Symbol("i"), Integer(1), (Integer(1) + Symbol("j")))); subs(v_b, v_j, 3)})), "ArrayComprehension(i, (i, 1, 4))")
  expect_equal(.bat_fmt(local({v_i <- Symbol("i"); ArrayComprehension(v_i, list(v_i, 1, 4))})), "ArrayComprehension(i, (i, 1, 4))")
  expect_equal(.bat_fmt(local({v_b <- ArrayComprehension(Symbol("i"), Tuple(Symbol("i"), Integer(1), (Integer(1) + Symbol("j")))); pyset(free_symbols(v_b))})), "{j}")
  expect_equal(.bat_fmt(local({v_b <- ArrayComprehension(Symbol("i"), Tuple(Symbol("i"), Integer(1), (Integer(1) + Symbol("j")))); get_shape(v_b)})), "[j + 1]")
  expect_equal(.bat_fmt(local({v_j <- Symbol("j"); list((v_j + 1))})), "[j + 1]")
  expect_equal(.bat_fmt(local({v_c <- ArrayComprehension((Symbol("i") + Symbol("j") + Symbol("k") + Symbol("l")), Tuple(Symbol("i"), Integer(1), Integer(2)), Tuple(Symbol("j"), Integer(1), Integer(3)), Tuple(Symbol("k"), Integer(1), Integer(4)), Tuple(Symbol("l"), Integer(1), Integer(5))); pyset(free_symbols(v_c))})), "{}")
  expect_equal(.bat_fmt(local({v_i <- Symbol("i"); v_j <- Symbol("j"); v_k <- Symbol("k"); v_l <- Symbol("l"); (((v_i + v_j) + v_k) + v_l)})), "i + j + k + l")
  expect_equal(.bat_fmt(local({v_i <- Symbol("i"); v_j <- Symbol("j"); v_k <- Symbol("k"); v_l <- Symbol("l"); list(list(v_i, 1, 2), list(v_j, 1, 3), list(v_k, 1, 4), list(v_l, 1, 5))})), "[[i, 1, 2], [j, 1, 3], [k, 1, 4], [l, 1, 5]]")
  expect_equal(.bat_fmt(local({list(list(list(list(4, 5, 6, 7, 8), list(5, 6, 7, 8, 9), list(6, 7, 8, 9, 10), list(7, 8, 9, 10, 11)), list(list(5, 6, 7, 8, 9), list(6, 7, 8, 9, 10), list(7, 8, 9, 10, 11), list(8, 9, 10, 11, 12)), list(list(6, 7, 8, 9, 10), list(7, 8, 9, 10, 11), list(8, 9, 10, 11, 12), list(9, 10, 11, 12, 13))), list(list(list(5, 6, 7, 8, 9), list(6, 7, 8, 9, 10), list(7, 8, 9, 10, 11), list(8, 9, 10, 11, 12)), list(list(6, 7, 8, 9, 10), list(7, 8, 9, 10, 11), list(8, 9, 10, 11, 12), list(9, 10, 11, 12, 13)), list(list(7, 8, 9, 10, 11), list(8, 9, 10, 11, 12), list(9, 10, 11, 12, 13), list(10, 11, 12, 13, 14))))})), "[[[[4, 5, 6, 7, 8], [5, 6, 7, 8, 9], [6, 7, 8, 9, 10], [7, 8, 9, 10, 11]], [[5, 6, 7, 8, 9], [6, 7, 8, 9, 10], [7, 8, 9, 10, 11], [8, 9, 10, 11, 12]], [[6, 7, 8, 9, 10], [7, 8, 9, 10, 11], [8, 9, 10, 11, 12], [9, 10, 11, 12, 13]]], [[[5, 6, 7, 8, 9], [6, 7, 8, 9, 10], [7, 8, 9, 10, 11], [8, 9, 10, 11, 12]], [[6, 7, 8, 9, 10], [7, 8, 9, 10, 11], [8, 9, 10, 11, 12], [9, 10, 11, 12, 13]], [[7, 8, 9, 10, 11], [8, 9, 10, 11, 12], [9, 10, 11, 12, 13], [10, 11, 12, 13, 14]]]]")
  expect_equal(.bat_fmt(local({v_i <- Symbol("i"); v_j <- Symbol("j"); v_k <- Symbol("k"); v_l <- Symbol("l"); list(v_i, v_j, v_k, v_l)})), "[i, j, k, l]")
  expect_equal(.bat_fmt(local({v_k <- Symbol("k"); list(v_k, v_k, v_k, v_k, v_k)})), "[k, k, k, k, k]")
  expect_error(local({v_i <- Symbol("i"); v_j <- Symbol("j"); ArrayComprehension((v_i * v_j), list(v_i, 1, 3), list(v_j, 2, list(1, 3, 2)))}), "Bounds should be an Expression(combination of Integer and Symbol)", fixed = TRUE, class = "TypeError")
  expect_error(local({v_i <- Symbol("i"); v_j <- Symbol("j"); ArrayComprehension((v_i * v_j), list(v_i, 1, 3), list(v_j, 2, 1))}), "Lower bound should be inferior to upper bound", fixed = TRUE, class = "ValueError")
  expect_error(local({v_i <- Symbol("i"); v_j <- Symbol("j"); ArrayComprehension((v_i * v_j), list(v_i, 1, 3), list(v_j, 2, (v_j + 1)))}), "Variable should not be part of its bounds", fixed = TRUE, class = "ValueError")
  expect_error(local({v_i <- Symbol("i"); v_j <- Symbol("j"); length(ArrayComprehension((v_i * v_j), list(v_i, 1, 3), list(v_j, 2, (v_j + 4))))}), "Variable should not be part of its bounds", fixed = TRUE, class = "ValueError")
  expect_error(local({v_i <- Symbol("i"); v_j <- Symbol("j"); ArrayComprehension((v_i * v_j), list(v_i, 0, (v_i + 1.5)), list(v_j, 0, 2))}), "Bounds should be an Expression(combination of Integer and Symbol)", fixed = TRUE, class = "TypeError")
})

test_that("test_array_comprehension: test_arraycomprehensionmap matches SymPy", {
  expect_equal(.bat_fmt(local({list(2, 3, 4, 5, 6)})), "[2, 3, 4, 5, 6]")
