  expect_equal(.bat_fmt(local({list(3, 3, 3, 3, 3)})), "[3, 3, 3, 3, 3]")
  expect_error(local({v_i <- Symbol("i"); v_j <- Symbol("j"); ArrayComprehensionMap((v_i * v_j), list(v_i, 1, 3), list(v_j, 2, 4))}), "Data type not supported", fixed = TRUE, class = "ValueError")
})

